export const questions = [
// ───────────────────────── L1 · The Lost Record (deepened + new) ─────────────────────────
  { id: 'l1-cascade', lectures: ['01'], type: 'concept',
    q: { en: 'Why is search done in two stages (retrieve → rank) instead of scoring the whole corpus with the best model?', ru: 'Почему поиск делают в два этапа (retrieve → rank), а не скорят весь корпус лучшей моделью?' },
    a: { en: 'The best scorer is a cross-encoder, which reads the (query, doc) pair jointly and costs roughly tens of ms per pair — running it over a ~10^9-doc corpus is about 10^8x over a 200ms budget, so it cannot scale. The cascade instead retrieves cheap-and-wide (BM25 / ANN, optimising recall) to shrink ~10^9 → ~10^3, then spends the expensive model on the few survivors (optimising precision@k). Each stage spends ~10x more compute on ~10x fewer candidates, which keeps total latency under SLA.', ru: 'Лучший оценщик — cross-encoder, читающий пару (запрос, документ) совместно ценой порядка десятков мс на пару; прогнать его по корпусу ~10^9 документов — это примерно в 10^8 раз больше бюджета 200 мс, он не масштабируется. Каскад вместо этого находит дёшево-вширь (BM25 / ANN, оптимизируя recall), сужая ~10^9 → ~10^3, затем тратит дорогую модель на немногих выживших (precision@k). Каждый этап тратит ~10× больше вычислений на ~10× меньше кандидатов, удерживая суммарную задержку под SLA.' },
    work: [
      'cascade  : 10^9  --retrieve-->  10^3  --rank-->  10^2  --rerank-->  10',
      'optimise :        recall              order             precision@k',
      'cost/doc :        very cheap          moderate          expensive',
      'why not score all: 10^9 docs x ~tens-of-ms = ~10^8x over the 200ms budget',
    ] },
  { id: 'l1-iceberg', lectures: ['01'], type: 'concept',
    q: { en: '"ML code is approx 5% of the iceberg." Name three of the larger hidden components of a production search system.', ru: '«ML-код приблизительно 5% айсберга». Назови три крупных скрытых компонента продакшн-поиска.' },
    a: { en: 'Sculley et al. (the "hidden technical debt" iceberg) point out the trained model is a tiny box; the bulk is engineering around it: configuration, data collection, feature extraction / a feature store, data verification, serving infrastructure, monitoring, process-management tooling, and analysis. The lesson for system design is that most of the failure modes and most of the work live outside the model code, so a good ML system is mostly disciplined data and serving engineering.', ru: 'Sculley et al. (айсберг «hidden technical debt») показывают, что обученная модель — крошечная коробка; основная масса — инженерия вокруг неё: конфигурация, сбор данных, извлечение признаков / feature store, верификация данных, serving-инфраструктура, мониторинг, управление процессами и аналитика. Урок для system design: большинство отказов и большая часть работы лежат вне ML-кода, так что хорошая ML-система — это в основном дисциплинированная инженерия данных и сервинга.' } },
  { id: 'l1-lexgap', lectures: ['01'], type: 'concept',
    q: { en: 'What is the lexical gap? Give an example of a relevant document that keyword search misses.', ru: 'Что такое lexical gap? Приведи пример релевантного документа, который key-word-поиск пропускает.' },
    a: { en: 'The lexical gap is the failure of exact term matching to bridge synonyms, paraphrase, and morphology: a query "couch" misses a relevant doc that only says "sofa", and "car insurance" misses "auto coverage". BM25 scores shared terms and has no notion of meaning, so two pages about the same thing in different words look unrelated to it. Closing this gap is exactly the motivation for the embedding / dense-retrieval half of the course (L5 onward).', ru: 'Lexical gap — неспособность точного совпадения слов мостить синонимы, перефраз и морфологию: запрос «couch» пропускает документ, где только «sofa», а «car insurance» — «auto coverage». BM25 скорит общие термы и не имеет понятия смысла, поэтому две страницы об одном и том же разными словами кажутся ему несвязанными. Закрытие этого разрыва и есть мотивация эмбеддинговой / dense-половины курса (с L5).' } },
  { id: 'l1-flywheel', lectures: ['01'], type: 'concept',
    q: { en: 'Describe a feedback loop ("flywheel") in a search system and how it becomes a rich-get-richer bias.', ru: 'Опиши feedback loop («flywheel») в поисковой системе и как он становится bias «rich-get-richer».' },
    a: { en: 'The loop is clicks → logs → training labels → ranking model → what gets shown → more clicks. Items shown high get clicked because they are on top (position bias), those clicks become positive training signal, the model ranks them higher still, and popularity compounds independently of true relevance. The system optimises a proxy (engagement) and silently entrenches whatever was already on top, which is why click logs are biased data, not ground truth, and need de-biasing or A/B confirmation.', ru: 'Цикл: клики → логи → метки обучения → модель ранжирования → что показано → ещё клики. Что показано выше — кликают потому что оно сверху (position bias), клики становятся позитивным сигналом, модель ранжирует это ещё выше, и популярность накапливается независимо от истинной релевантности. Система оптимизирует прокси (вовлечённость) и молча закрепляет уже бывшее наверху — поэтому клик-логи это смещённые данные, а не истина, и требуют де-биасинга или подтверждения A/B.' } },
  { id: 'l1-goodhart', lectures: ['01', '04'], type: 'concept',
    q: { en: 'State Goodhart\'s law with a search-specific example.', ru: 'Сформулируй закон Гудхарта на примере из поиска.' },
    a: { en: 'Goodhart\'s law: when a measure becomes a target, it stops being a good measure. In search, optimising click-through rate (a proxy for satisfaction) rewards clickbait titles and thumbnail bait, so CTR climbs while real user satisfaction and dwell time fall. The defence is to never trust a single proxy: triangulate offline graded metrics, significance tests, guardrail metrics (dwell, return rate), and live A/B tests so no one number can be gamed.', ru: 'Закон Гудхарта: когда метрика становится целью, она перестаёт быть хорошей метрикой. В поиске оптимизация CTR (прокси удовлетворённости) награждает кликбейт-заголовки и приманки-превью, поэтому CTR растёт, а реальное удовлетворение и dwell time падают. Защита — не доверять одному прокси: триангулируй оффлайн-градуированные метрики, тесты значимости, guardrail-метрики (dwell, возвраты) и живой A/B, чтобы ни одно число нельзя было загеймить.' } },
  { id: 'l1-bruteforce', lectures: ['01'], type: 'compute',
    q: { en: 'Back-of-envelope: a cross-encoder scores at ~50 ms/doc and the corpus has 1,000,000 docs. Show why brute-force O(N) scoring per query is infeasible, and how a bi-encoder makes it cheap.', ru: 'На салфетке: cross-encoder скорит ~50 мс/документ, в корпусе 1 000 000 документов. Покажи, почему перебор O(N) на запрос неподъёмен и как bi-encoder делает это дёшево.' },
    a: { en: 'Scoring every document with a cross-encoder is 50 ms x 1,000,000 = 50,000,000 ms = 50,000 s, about 13.9 hours per single query, because the score is a property of the (q, d) pair and nothing can be cached. A bi-encoder breaks the dependence: it encodes each document offline once into a vector, so at query time you encode the query once (~50 ms) and reduce scoring to ~10^6 cheap dot products, which finishes in well under a second. The lesson is that precompute-then-dot turns an O(N) model-pass-per-doc cost into an O(N) cheap-arithmetic cost — many orders of magnitude smaller — which is the whole reason dense retrieval is a first-stage retriever and cross-encoders are reserved for reranking.', ru: 'Скорить каждый документ cross-encoder\'ом — это 50 мс x 1 000 000 = 50 000 000 мс = 50 000 с, около 13,9 часа на один запрос, потому что оценка — свойство пары (q, d) и кэшировать нечего. Bi-encoder рвёт зависимость: он кодирует каждый документ офлайн один раз в вектор, поэтому на запросе кодируешь запрос один раз (~50 мс) и сводишь скоринг к ~10^6 дешёвых dot product\'ов, что укладывается заметно меньше секунды. Урок: предпосчёт-затем-dot превращает стоимость O(N) прогонов модели на документ в стоимость O(N) дешёвой арифметики — на много порядков меньше, — и это вся причина, почему dense — первый этап, а cross-encoder приберегают для реранка.' },
    work: [
      'N = 1,000,000 docs   cross-encoder = 50 ms / doc',
      'brute force  : 50 ms x 1e6 = 5e7 ms = 5e4 s ~ 13.9 hours  PER QUERY  (no caching: score is per-pair)',
      'bi-encoder offline : encode 1e6 doc vectors ONCE (reused for every query)',
      'bi-encoder online  : encode query ~50 ms  +  1e6 dot products',
      '  one 768-d dot ~ 768 mul+add ;  1e6 x 768 ~ 7.7e8 flops  <  1 s on CPU',
      'speedup  : ~5e4 s  ->  < 1 s   (>1e4 x)  ;  cross-encoder kept for reranking only',
    ] },
  { id: 'l1-funnel', lectures: ['01'], type: 'compute',
    q: { en: 'Put numbers on the retrieve → rank → rerank funnel (10^6 → 10^3 → 10) and show the cost spent at each stage; compare the rerank cost to scoring the whole corpus.', ru: 'Поставь числа на воронку retrieve → rank → rerank (10^6 → 10^3 → 10) и покажи стоимость на каждом этапе; сравни стоимость реранка с прогоном по всему корпусу.' },
    a: { en: 'The funnel shrinks the candidate set by about 10x at each stage so each stage can afford a ~10x more expensive model: cheap BM25/ANN over 10^6 (optimising recall), a moderate GBDT/LTR over the ~10^3 survivors, then an expensive cross-encoder over only ~10 (optimising precision@k). Putting a 50 ms cross-encoder only on the final ~10 docs costs ~500 ms, versus ~13.9 hours to run it over all 10^6 — the same accurate model becomes affordable purely because the funnel handed it a tiny set. The catch is the recall ceiling: anything stage-1 drops can never be recovered, so the funnel only works if early recall is high.', ru: 'Воронка сужает множество кандидатов примерно в 10× на каждом этапе, чтобы этап мог позволить себе модель в ~10× дороже: дешёвый BM25/ANN по 10^6 (recall), умеренный GBDT/LTR по ~10^3 выжившим, затем дорогой cross-encoder только по ~10 (precision@k). Поставить 50-мс cross-encoder лишь на финальные ~10 документов стоит ~500 мс против ~13,9 часа на прогон по всем 10^6 — та же точная модель становится посильной только потому, что воронка отдала ей крошечное множество. Подвох — recall-потолок: всё, что отброшено на 1-м этапе, не вернуть, так что воронка работает лишь при высоком раннем recall.' },
    work: [
      'stage      set size   model            cost/doc     ~ stage cost',
      'retrieve   1e6        BM25 / ANN       very cheap   sublinear (skip-lists / index)',
      'rank       1e3        GBDT / LTR       moderate     1e3 x moderate',
      'rerank     1e1        cross-encoder    50 ms        10 x 50 ms = 500 ms',
      'contrast : same cross-encoder over ALL 1e6 = 1e6 x 50 ms ~ 13.9 h',
      'so rerank is affordable ONLY because the funnel cut 1e6 -> 10  (~1e5 x fewer)',
      'recall ceiling: if stage-1 recall = 80%, a perfect reranker still caps at 80%',
    ] },

  // ───────────────────────── L2 · First Contact (deepened + new) ─────────────────────────
  { id: 'l2-bpe', lectures: ['02'], type: 'compute',
    q: { en: 'Run the BPE merge loop on the toy string aaabdaaabac; show the full merge ledger and the final symbol count.', ru: 'Прогони цикл BPE-слияний на toy-строке aaabdaaabac; покажи полный merge-ledger и итоговое число символов.' },
    a: { en: 'BPE repeatedly counts adjacent symbol pairs, merges the single most frequent pair into a new symbol, and repeats. On aaabdaaabac (11 chars) the most frequent pair aa (twice) merges to Z; then ab (twice) merges to Y; then ZY (twice) merges to X, leaving XdXac with 5 symbols and no repeated adjacent pair. The ordered ledger {aa->Z, ab->Y, ZY->X} is the learned vocabulary, and re-applied in that exact order it tokenizes new text — the same loop on a frequency-weighted word corpus is the subword tokenizer.', ru: 'BPE раз за разом считает соседние пары символов, сливает единственную самую частую пару в новый символ и повторяет. На aaabdaaabac (11 симв.) самая частая пара aa (дважды) сливается в Z; затем ab (дважды) в Y; затем ZY (дважды) в X, оставляя XdXac — 5 символов и ни одной повторяющейся соседней пары. Упорядоченный ledger {aa->Z, ab->Y, ZY->X} — это выученный словарь, и применённый ровно в том же порядке он токенизирует новый текст — тот же цикл на частотно-взвешенном корпусе слов даёт subword-токенизатор.' },
    work: [
      'start : a a a b d a a a b a c            (11 symbols)',
      'count pairs: aa=2  ab=2  ... -> top = aa',
      'merge 1  aa->Z : Z a b d Z a b a c       (9)   ledger: aa->Z',
      'count pairs: ab=2 -> top',
      'merge 2  ab->Y : Z Y d Z Y a c           (7)   ledger: ab->Y',
      'count pairs: ZY=2 -> top',
      'merge 3  ZY->X : X d X a c                (5)   ledger: ZY->X',
      'stop: no adjacent pair repeats. 11 -> 5 symbols, vocab = {aa,ab,ZY}',
    ] },
  { id: 'l2-bpe-corpus', lectures: ['02'], type: 'compute',
    q: { en: 'Train BPE on the word corpus {low^5, lower^2, newest^6, widest^3}: do the frequency-weighted pair counts and the first merges, then tokenize the unseen word "lowest".', ru: 'Обучи BPE на корпусе слов {low^5, lower^2, newest^6, widest^3}: посчитай частотно-взвешенные пары, сделай первые слияния и токенизируй невиданное слово «lowest».' },
    a: { en: 'Each word is split into characters plus an end-of-word marker </w> and pair counts are weighted by the word\'s corpus frequency, so the pair "e s" scores 6 (newest) + 3 (widest) = 9, the maximum. Merging gives es (9), then est (9), then est</w> (9), then lo (7 = low^5 + lower^2) and low (7). The payoff: "lowest" never appeared in training, yet it tokenizes cleanly as low + est</w> from the learned pieces — no [UNK] token — which is exactly why subword tokenization generalises to unseen and inflected words.', ru: 'Каждое слово разбивается на символы плюс маркер конца слова </w>, а счёт пар взвешивается частотой слова, так что пара «e s» даёт 6 (newest) + 3 (widest) = 9 — максимум. Слияния дают es (9), затем est (9), затем est</w> (9), затем lo (7 = low^5 + lower^2) и low (7). Выигрыш: «lowest» не встречалось в обучении, но токенизируется чисто как low + est</w> из выученных кусков — без [UNK], — и именно поэтому subword обобщается на невиданные и словоформенные слова.' },
    work: [
      'corpus (with freq):  low^5  lower^2  newest^6  widest^3',
      'split: low->l o w </w> ; newest->n e w e s t </w> ; widest->w i d e s t </w>',
      'pair counts (freq-weighted):',
      '  e s = 6 + 3 = 9   <- max      s t = 6 + 3 = 9      l o = 5 + 2 = 7',
      'merge 1  e+s -> es      (9)',
      'merge 2  es+t -> est    (9)',
      'merge 3  est+</w> -> est</w>  (9)',
      'merge 4  l+o -> lo      (7)',
      'merge 5  lo+w -> low    (7)',
      'tokenize UNSEEN "lowest": l o w e s t </w> -> low + est</w>   (no UNK)',
    ] },
  { id: 'l2-subword', lectures: ['02'], type: 'concept',
    q: { en: 'Why do sub-word tokenizers (BPE/WordPiece) beat whole-word on OOV and morphology?', ru: 'Почему sub-word (BPE/WordPiece) бьёт whole-word на OOV и морфологии?' },
    a: { en: 'A whole-word vocabulary is fixed at training time, so any word it never saw falls out as [UNK], destroying information; sub-word tokenizers instead share a vocabulary of reusable pieces, so a rare or inflected or never-seen word decomposes into known sub-units (e.g. "lowest" -> low + est) with no UNK. This also captures morphology for free: shared stems and suffixes ("play", "##ing", "##ed") are reused across words, giving the model a notion of word structure and keeping the vocabulary bounded while coverage stays open.', ru: 'Whole-word-словарь фиксирован на обучении, поэтому любое невиданное слово выпадает как [UNK], теряя информацию; sub-word вместо этого делят словарь переиспользуемых кусков, и редкое, словоформенное или невиданное слово раскладывается на известные под-единицы (напр. «lowest» -> low + est) без UNK. Это заодно бесплатно ловит морфологию: общие основы и суффиксы («play», «##ing», «##ed») переиспользуются между словами, давая модели понятие структуры слова и держа словарь ограниченным при открытом покрытии.' } },
  { id: 'l2-wordpiece-bpe-unigram', lectures: ['02'], type: 'concept',
    q: { en: 'Contrast BPE, WordPiece, and Unigram-SentencePiece: how does each choose its merges/tokens — frequency vs likelihood?', ru: 'Сравни BPE, WordPiece и Unigram-SentencePiece: как каждый выбирает слияния/токены — частота vs правдоподобие?' },
    a: { en: 'All three end with a bounded sub-word vocabulary but differ in how they pick it. BPE builds bottom-up, greedily merging the single most frequent adjacent pair (pure count). WordPiece also builds bottom-up but merges the pair that most increases corpus likelihood, scored as freq(AB)/(freq(A)*freq(B)) — a PMI-like measure that favours pairs co-occurring more than chance, and it marks word-internal pieces with ##. Unigram-SentencePiece goes top-down: it seeds a large vocabulary, fits a unigram language model, and prunes the tokens whose removal least hurts corpus likelihood until the target size; SentencePiece additionally treats whitespace as an ordinary symbol (rendered _) so it is reversible and language-agnostic. One-liner: BPE = most-frequent pair, WordPiece = highest likelihood gain, Unigram = least likelihood loss.', ru: 'Все три заканчиваются ограниченным sub-word-словарём, но различаются тем, как его выбирают. BPE строит снизу вверх, жадно сливая единственную самую частую соседнюю пару (чистый счёт). WordPiece тоже строит снизу вверх, но сливает пару, максимально увеличивающую правдоподобие корпуса, со счётом freq(AB)/(freq(A)*freq(B)) — PMI-подобная мера, поощряющая пары, встречающиеся чаще случайного, и помечает внутрисловные куски через ##. Unigram-SentencePiece идёт сверху вниз: засевает большой словарь, обучает unigram-языковую модель и отсекает токены, удаление которых меньше всего вредит правдоподобию, до целевого размера; SentencePiece вдобавок трактует пробел как обычный символ (рендерит _), поэтому он обратим и языко-независим. Одной строкой: BPE = самая частая пара, WordPiece = наибольший прирост правдоподобия, Unigram = наименьшая потеря правдоподобия.' },
    work: [
      'algorithm  direction          criterion                         marker  used by',
      'BPE        bottom-up (merge)  most FREQUENT pair                byte    GPT-2/4, RoBERTa',
      'WordPiece  bottom-up (merge)  highest LIKELIHOOD gain (PMI-ish) ##      BERT',
      'Unigram    top-down  (prune)  least LIKELIHOOD loss             _       T5, LLaMA, Mistral',
      'WordPiece score(A,B) = freq(AB) / ( freq(A) * freq(B) )',
      '  (some impls use freq(AB)*|V| / (freq(A)*freq(B)); the merge ordering is unchanged)',
    ] },
  { id: 'l2-wordpiece-score', lectures: ['02'], type: 'compute',
    q: { en: 'WordPiece picks merges by score(A,B) = freq(AB)/(freq(A)*freq(B)), not raw frequency. On toy counts, show a frequent-but-common pair losing to a rarer-but-sticky pair.', ru: 'WordPiece выбирает слияния по score(A,B) = freq(AB)/(freq(A)*freq(B)), а не по сырой частоте. На toy-счётчиках покажи, как частая-но-обычная пара проигрывает редкой-но-липкой.' },
    a: { en: 'The denominator divides by the marginal counts of each piece, so a pair of two very common pieces (th + ##e) gets a big numerator but an even bigger denominator and scores low, while a pair where a piece almost always glues to one specific neighbour (un + ##able) scores high even at lower raw frequency. This is pointwise mutual information without the log: it rewards co-occurrence beyond chance, which is why WordPiece tends to keep meaningful morphemes together rather than just gluing the commonest characters. So WordPiece can prefer a merge that BPE (which only looks at raw frequency) would skip.', ru: 'Знаменатель делит на маргинальные счётчики каждого куска, поэтому пара двух очень частых кусков (th + ##e) даёт большой числитель, но ещё больший знаменатель и низкий score, тогда как пара, где кусок почти всегда клеится к одному соседу (un + ##able), даёт высокий score даже при меньшей сырой частоте. Это pointwise mutual information без логарифма: награждается совстречаемость сверх случайной — поэтому WordPiece склонен держать осмысленные морфемы вместе, а не просто склеивать самые частые символы. Так WordPiece может предпочесть слияние, которое BPE (смотрящий лишь на сырую частоту) пропустил бы.' },
    work: [
      'score(A,B) = freq(AB) / ( freq(A) * freq(B) )',
      'pair  (th, ##e):  freq(AB)=30  freq(th)=30  freq(##e)=100',
      '   score = 30 / (30 * 100) = 30 / 3000 = 0.010',
      'pair  (un, ##able): freq(AB)=10  freq(un)=10  freq(##able)=10',
      '   score = 10 / (10 * 10)  = 10 / 100  = 0.100',
      'BPE (raw freq): picks (th,##e), freq 30 > 10',
      'WordPiece (score): picks (un,##able), 0.100 > 0.010  <- sticky morpheme wins',
      '(some impls scale by |V|: freq(AB)*|V|/(freq(A)*freq(B)); merge ORDER unchanged)',
    ] },
  { id: 'l2-token-tax', lectures: ['02'], type: 'concept',
    q: { en: 'What is the multilingual "token tax" / fertility, and why does it make low-resource languages cost more to serve?', ru: 'Что такое мультиязычный «token tax» / fertility и почему он делает дороже обслуживание низкоресурсных языков?' },
    a: { en: 'Fertility is tokens-per-word; a tokenizer trained mostly on English splits English cheaply but shatters other scripts into many byte-level pieces — e.g. a 16k BPE trained on (mostly English) 20 Newsgroups turns the Russian word "привет" into 12 tokens while English "tokenization" takes 3. Because attention is O(n^2), roughly 2x fertility means about 4x training compute, about 2x API price and latency, and a smaller effective context window for the same content. This is a fairness problem, not just efficiency: low-resource-language speakers pay more for slower, worse service on identical information.', ru: 'Fertility — это токенов-на-слово; токенизатор, обученный в основном на английском, дёшево режет английский, но дробит другие письменности на много byte-level кусков — напр. 16k BPE, обученный на (в основном английском) 20 Newsgroups, превращает русское «привет» в 12 токенов, а английское «tokenization» — в 3. Поскольку attention — это O(n^2), примерно 2× fertility означает около 4× обучающих вычислений, около 2× цены API и задержки и меньшее эффективное окно контекста для того же содержания. Это проблема справедливости, не только эффективности: носители низкоресурсных языков платят больше за более медленный и худший сервис на идентичной информации.' },
    work: [
      'fertility = tokens / word   (a CORPUS AVERAGE, not one word)',
      'per-word examples (different words, illustrative only):',
      '  English  "tokenization"  -> 3 tokens',
      '  Russian  "privet"        -> 12 byte-level tokens  (16k BPE, mostly-English)',
      'corpus-average fertility (RU vs EN) ~ 2x   <- the figure that drives cost',
      '  (do NOT read 12/3 = 4x: those are two DIFFERENT words, not the ratio)',
      'attention O(n^2) : ~2x fertility -> ~4x train compute',
      '                   ~2x API cost , ~2x latency , ~half the usable context window',
    ] },
  { id: 'l2-zipf-heaps', lectures: ['02'], type: 'concept',
    q: { en: 'State Zipf\'s and Heaps\' laws and what each implies for an IR system.', ru: 'Сформулируй законы Zipf и Heaps и что каждый значит для IR.' },
    a: { en: 'Zipf\'s law: a term\'s frequency is roughly inversely proportional to its rank (frequency proportional to 1/rank), so a handful of head terms dominate and a long tail of rare terms remains — this is why idf weighting and stopword handling matter, since common words carry little discriminating signal. Heaps\' law: vocabulary size grows sub-linearly (about V proportional to n^beta, beta around 0.5) with corpus size n, so you keep seeing new terms no matter how large the corpus gets — which is precisely why a fixed whole-word vocabulary fails on OOV and why sub-word tokenization is needed.', ru: 'Закон Zipf: частота терма примерно обратно пропорциональна его рангу (частота пропорциональна 1/ранг), так что горстка «головных» термов доминирует, а длинный хвост редких остаётся — поэтому важны idf-взвешивание и стоп-слова, ведь частые слова несут мало различающего сигнала. Закон Heaps: размер словаря растёт сублинейно (около V пропорционально n^beta, beta около 0,5) с размером корпуса n, так что новые термы появляются сколь угодно большим корпусом — именно поэтому фиксированный whole-word словарь проваливается на OOV и нужен sub-word.' } },
  { id: 'l2-cosine', lectures: ['02'], type: 'compute',
    q: { en: 'Compute the cosine similarity of a=(1,2,2) and b=(2,0,1) by hand (dot, norms, divide); then say why text uses cosine rather than Euclidean.', ru: 'Посчитай cosine для a=(1,2,2) и b=(2,0,1) руками (dot, нормы, деление); затем объясни, почему для текста косинус, а не евклид.' },
    a: { en: 'cos = (a . b)/(||a|| ||b||): the dot is 1*2 + 2*0 + 2*1 = 4, the norms are sqrt(1+4+4)=3 and sqrt(4+0+1)=sqrt(5)~2.236, so cos = 4/(3*sqrt(5)) = 4/6.708 ~ 0.596, an angle of about 53 degrees ("moderately similar"). Text uses cosine because it is length-invariant: it measures only the direction (the topic mix), so a long document is not scored as more relevant just for repeating words, which is exactly the artifact raw dot product or Euclidean distance on raw counts would introduce.', ru: 'cos = (a . b)/(||a|| ||b||): dot равен 1*2 + 2*0 + 2*1 = 4, нормы sqrt(1+4+4)=3 и sqrt(4+0+1)=sqrt(5)~2.236, поэтому cos = 4/(3*sqrt(5)) = 4/6.708 ~ 0.596, угол около 53 градусов («умеренно похожи»). Текст использует косинус, потому что он инвариантен к длине: меряет только направление (смесь тем), так что длинный документ не считается релевантнее просто за повтор слов — а именно этот артефакт внесли бы сырой dot или евклид на сырых счётчиках.' },
    work: [
      'a = (1, 2, 2)   b = (2, 0, 1)',
      'dot   a.b = 1*2 + 2*0 + 2*1 = 2 + 0 + 2 = 4',
      'norm  ||a|| = sqrt(1^2+2^2+2^2) = sqrt(9)  = 3',
      'norm  ||b|| = sqrt(2^2+0^2+1^2) = sqrt(5)  ~ 2.236',
      'cos = 4 / (3 * 2.236) = 4 / 6.708 ~ 0.596',
      'angle = arccos(0.596) ~ 53.4 deg  -> moderately similar',
    ] },
  { id: 'l2-cos-vs-euclid', lectures: ['02'], type: 'compute',
    q: { en: 'Two vectors share a direction but differ in magnitude: u=(1,1) vs v=(10,10). Compute cosine and Euclidean by hand and say what each measure concludes.', ru: 'Два вектора одного направления, но разной длины: u=(1,1) и v=(10,10). Посчитай cosine и евклид руками и скажи, что заключает каждая мера.' },
    a: { en: 'Cosine is exactly 1.0: the dot is 20 and the norm-product is sqrt(2)*sqrt(200) = sqrt(400) = 20, so 20/20 = 1 — identical, because they point the same way. Euclidean distance is large: sqrt((1-10)^2 + (1-10)^2) = sqrt(162) ~ 12.73 — far apart, because magnitudes differ tenfold. For text we usually want the angle (the topic), not the length, so cosine treats these as the same document at different verbosity while Euclidean wrongly penalises the longer one; the two agree only on L2-normalized vectors.', ru: 'Косинус ровно 1,0: dot равен 20, а произведение норм sqrt(2)*sqrt(200) = sqrt(400) = 20, так что 20/20 = 1 — идентичны, ведь направление одно. Евклидово расстояние велико: sqrt((1-10)^2 + (1-10)^2) = sqrt(162) ~ 12,73 — далеко, ведь величины различаются в десять раз. Для текста обычно нужен угол (тема), а не длина, поэтому косинус считает их одним документом разной многословности, а евклид ошибочно штрафует более длинный; совпадают они только на L2-нормированных векторах.' },
    work: [
      'u = (1, 1)   v = (10, 10)   (same direction)',
      'dot   u.v = 1*10 + 1*10 = 20',
      '||u|| = sqrt(1+1) = sqrt(2) ~ 1.414',
      '||v|| = sqrt(100+100) = sqrt(200) = 10*sqrt(2) ~ 14.14',
      'cos = 20 / (sqrt(2) * 10*sqrt(2)) = 20 / (10*2) = 20/20 = 1.0   -> identical',
      'euclid ||u-v|| = sqrt((1-10)^2 + (1-10)^2) = sqrt(81+81) = sqrt(162) ~ 12.73  -> far',
    ] },
  { id: 'l2-jaccard', lectures: ['02'], type: 'compute',
    q: { en: 'Compute the Jaccard similarity and Jaccard distance of two short token sets by hand.', ru: 'Посчитай руками Jaccard-сходство и Jaccard-расстояние двух коротких множеств токенов.' },
    a: { en: 'Jaccard similarity is J(A,B) = |A intersect B| / |A union B|, the fraction of the combined vocabulary the two sets share. For A = {the, quick, brown, fox} and B = {the, lazy, brown, dog}, the intersection is {the, brown} (size 2) and the union is {the, quick, brown, fox, lazy, dog} (size 6), so J = 2/6 = 1/3 ~ 0.333, and the Jaccard distance 1 - J = 2/3 ~ 0.667 (a true metric). Jaccard is the natural measure for sets/bags — shingled documents, categorical features, user-item interactions — and MinHash estimates it at web scale because the probability two sketches collide equals exactly J.', ru: 'Jaccard-сходство это J(A,B) = |A пересечение B| / |A объединение B|, доля общего словаря, которую делят два множества. Для A = {the, quick, brown, fox} и B = {the, lazy, brown, dog} пересечение {the, brown} (размер 2), объединение {the, quick, brown, fox, lazy, dog} (размер 6), поэтому J = 2/6 = 1/3 ~ 0,333, а Jaccard-расстояние 1 - J = 2/3 ~ 0,667 (настоящая метрика). Jaccard — естественная мера для множеств/мешков (шинглы документов, категориальные признаки, взаимодействия user-item), а MinHash оценивает её на веб-масштабе, ведь вероятность коллизии двух скетчей равна ровно J.' },
    work: [
      'A = { the, quick, brown, fox }   B = { the, lazy, brown, dog }',
      'A intersect B = { the, brown }                 -> |.| = 2',
      'A union B     = { the, quick, brown, fox, lazy, dog } -> |.| = 6',
      'J(A,B) = 2 / 6 = 1/3 ~ 0.333',
      'Jaccard distance = 1 - J = 1 - 0.333 = 2/3 ~ 0.667  (a true metric)',
    ] },
  { id: 'l2-dot-mips', lectures: ['02'], type: 'concept',
    q: { en: 'Dot product vs cosine and MIPS: why normalize, and when does maximum-inner-product search disagree with cosine?', ru: 'Dot product vs cosine и MIPS: зачем нормировать и когда maximum-inner-product search расходится с косинусом?' },
    a: { en: 'The dot product a.b = ||a|| ||b|| cos(theta) is cosine without the normalization, so it rewards both direction and magnitude and its range is the whole line (it is not a metric). You normalize (use cosine) when length is an artifact rather than signal — e.g. raw TF-IDF, where a long document scores high just for being long. But trained dual encoders (DPR) deliberately learn meaningful norms, pushing confident, information-rich passages to larger magnitude, so MIPS (argmax a.b) intentionally rewards that length and disagrees with cosine: two candidates with the same direction but different norms tie under cosine yet MIPS strictly prefers the larger-norm one. So normalize when magnitude is noise, score by dot when the model was trained to put signal in the length.', ru: 'Скалярное произведение a.b = ||a|| ||b|| cos(theta) это косинус без нормировки, поэтому оно награждает и направление, и величину, а его диапазон — вся прямая (это не метрика). Нормируешь (берёшь косинус), когда длина — артефакт, а не сигнал, напр. сырой TF-IDF, где длинный документ набирает много просто за длину. Но обученные dual encoders (DPR) нарочно учат осмысленные нормы, выталкивая уверенные, информативные пассажи к большей величине, поэтому MIPS (argmax a.b) намеренно награждает эту длину и расходится с косинусом: два кандидата одного направления, но разной нормы, под косинусом равны, а MIPS строго предпочтёт того, у кого норма больше. Итог: нормируй, когда величина — шум; скорь dot\'ом, когда модель обучена класть сигнал в длину.' },
    work: [
      'a . b = sum_i a_i b_i = ||a|| ||b|| cos(theta)   (cosine WITHOUT normalization)',
      'worked: u=(2,-3), v=(4,2) -> 2*4 + (-3)*2 = 8 - 6 = 2',
      'MIPS != cosine example:  q=(1,0)  a=(1,0)  b=(3,0)',
      '  cos(q,a)=1   cos(q,b)=1            -> cosine TIES (same direction)',
      '  q.a = 1      q.b = 3               -> MIPS prefers b (bigger norm = learned signal)',
      'rule: normalize when length is artifact (raw TF-IDF); dot when norms are trained signal (DPR)',
    ] },
  { id: 'l2-curse', lectures: ['02'], type: 'concept',
    q: { en: 'The curse of dimensionality: what are distance concentration, hubness, and anisotropy, and how do they hurt nearest-neighbour search?', ru: 'Проклятие размерности: что такое концентрация расстояний, hubness и anisotropy и чем они вредят kNN-поиску?' },
    a: { en: 'Distance concentration: in high dimensions the ratio of the farthest to the nearest pairwise distance approaches 1, so all points look about equally far and there is no contrast to rank by. Hubness: a few points become "hubs" that appear in a disproportionate number of other points\' nearest-neighbour lists, distorting retrieval. Anisotropy: learned embeddings crowd into a narrow cone rather than filling the space, so cosines are all high and undiscriminative. Together they erode the signal nearest-neighbour search relies on, which is why we whiten / contrastively train embeddings and use ANN structures rather than trusting raw high-dimensional distances.', ru: 'Концентрация расстояний: в высокой размерности отношение самого дальнего к ближайшему попарному расстоянию стремится к 1, поэтому все точки кажутся примерно равноудалёнными и нет контраста для ранжирования. Hubness: немногие точки становятся «хабами», попадая в непропорционально много чужих списков соседей, искажая поиск. Anisotropy: выученные эмбеддинги жмутся в узкий конус, а не заполняют пространство, поэтому косинусы все высокие и неразличающие. Вместе они разъедают сигнал, на котором держится kNN-поиск, — поэтому мы whitening-уем / контрастно обучаем эмбеддинги и используем ANN-структуры, а не доверяем сырым высокоразмерным расстояниям.' } },

// ───────────────────────── L3 · DEEPENED ─────────────────────────
  { id: 'l3-invindex', lectures: ['03'], type: 'concept',
    q: { en: 'Why an inverted index instead of a linear scan? What does a postings list store, and what is the rarest-term-first optimization for a conjunctive query?', ru: 'Зачем инвертированный индекс вместо линейного скана? Что хранит постинг-лист и в чём оптимизация «сначала редкий терм» для конъюнктивного запроса?' },
    a: { en: 'A linear scan is O(N·|d|) per query — unusable at web scale. An inverted index maps term → postings list [(doc_id, tf, positions), …] sorted by doc_id, so you visit only the docs that actually contain a query term. Postings also carry doc lengths and term positions (for phrase/proximity). For an AND of several terms, intersect starting from the rarest term (smallest df): the running result can only shrink, so each later merge runs against a tiny list.', ru: 'Линейный скан — O(N·|d|) на запрос, на веб-масштабе непригоден. Инвертированный индекс отображает терм → постинг-лист [(doc_id, tf, позиции), …], отсортированный по doc_id, и ты обходишь только документы, реально содержащие терм. Постинги хранят и длины документов, и позиции (для фраз/близости). Для AND нескольких термов пересекай начиная с самого редкого (наименьший df): промежуточный результат может только сокращаться, и каждое следующее слияние идёт против крошечного списка.' },
    work: [
      'cat   -> [1, 2, 4, 5]   df=4',
      'dog   -> [2, 4, 5]      df=3',
      'bird  -> [1, 5]         df=2',
      '',
      'cat AND dog  =  {1,2,4,5} ∩ {2,4,5}  = [2, 4, 5]',
      'plan: start from rarest (bird, df=2):',
      '  bird ∩ cat = {1,5} ∩ {1,2,4,5} = {1,5}   (already tiny)',
      '  vs. starting cat ∩ dog first scans the long list',
    ] },
  { id: 'l3-bm25-compute', lectures: ['03'], type: 'compute',
    q: { en: 'Compute a full BM25 term score given tf=3, df=10, N=1000, |d|=200, avgdl=250, with k₁=1.5, b=0.75. Show idf, the length bracket, the saturating tf factor, and the final number.', ru: 'Посчитай полный вклад терма BM25 при tf=3, df=10, N=1000, |d|=200, avgdl=250, k₁=1.5, b=0.75. Покажи idf, скобку длины, насыщающий tf-фактор и итоговое число.' },
    a: { en: 'score = idf · tf·(k₁+1) / (tf + k₁·(1 − b + b·|d|/avgdl)), with smoothed idf = ln(1 + (N−df+0.5)/(df+0.5)). Here idf = ln(1+990.5/10.5) = 4.5574, the length bracket = 0.25 + 0.75·(200/250) = 0.85 (doc shorter than average → mild boost), the tf factor B = 3·2.5/(3 + 1.5·0.85) = 7.5/4.275 = 1.7544, so score = 4.5574·1.7544 ≈ 7.9954. The rare term (df=10 of 1000) carries most of the weight via its large idf.', ru: 'score = idf · tf·(k₁+1) / (tf + k₁·(1 − b + b·|d|/avgdl)), сглаженный idf = ln(1 + (N−df+0.5)/(df+0.5)). Здесь idf = ln(1+990.5/10.5) = 4.5574, скобка длины = 0.25 + 0.75·(200/250) = 0.85 (документ короче среднего → лёгкий буст), tf-фактор B = 3·2.5/(3 + 1.5·0.85) = 7.5/4.275 = 1.7544, итог score = 4.5574·1.7544 ≈ 7.9954. Редкий терм (df=10 из 1000) несёт основной вес за счёт большого idf.' },
    work: [
      'tf=3  df=10  N=1000  |d|=200  avgdl=250  k1=1.5  b=0.75',
      '',
      'idf = ln(1 + (N − df + 0.5)/(df + 0.5))',
      '    = ln(1 + (1000 − 10 + 0.5)/(10 + 0.5))',
      '    = ln(1 + 990.5/10.5) = ln(95.333) = 4.5574',
      '',
      'bracket = (1 − b) + b·|d|/avgdl',
      '        = 0.25 + 0.75·(200/250) = 0.25 + 0.75·0.8 = 0.85',
      '',
      'B = tf·(k1+1) / (tf + k1·bracket)',
      '  = 3·2.5 / (3 + 1.5·0.85) = 7.5 / 4.275 = 1.7544',
      '',
      'score = idf · B = 4.5574 · 1.7544 = 7.9954',
    ] },
  { id: 'l3-k1-b', lectures: ['03'], type: 'concept',
    q: { en: 'In BM25, what do k₁ and b control? What happens at b=0 and b=1, and at k₁→0 vs k₁→∞? Show the length bracket at b=0 and b=1 for a doc twice the average length.', ru: 'Что регулируют k₁ и b в BM25? Что на краях b=0 и b=1, и при k₁→0 vs k₁→∞? Покажи скобку длины при b=0 и b=1 для документа вдвое длиннее среднего.' },
    a: { en: 'k₁ sets term-frequency saturation: small k₁ makes the tf factor flatten almost immediately (one occurrence ≈ many), large k₁ keeps tf nearly linear. b sets document-length normalization: b=0 turns it off (bracket = 1 always, length ignored), b=1 applies it fully (bracket = |d|/avgdl). For |d| = 2·avgdl the bracket is 1.0 at b=0 but 2.0 at b=1, so the long doc is penalised twice as hard — its repeated terms are discounted as padding.', ru: 'k₁ задаёт насыщение по частоте терма: малый k₁ почти сразу выравнивает tf-фактор (одно вхождение ≈ много), большой k₁ держит tf почти линейным. b задаёт нормировку длины: b=0 отключает её (скобка всегда = 1, длина игнорируется), b=1 включает полностью (скобка = |d|/avgdl). При |d| = 2·avgdl скобка равна 1.0 при b=0, но 2.0 при b=1, и длинный документ штрафуется вдвое — его повторы считаются «водой».' },
    work: [
      'bracket = (1 − b) + b·|d|/avgdl,   take |d| = 2·avgdl  (ratio = 2)',
      '',
      'b = 0:  bracket = 1 + 0·2 = 1.0     → length ignored',
      'b = 1:  bracket = 0 + 1·2 = 2.0     → full length penalty',
      'b = 0.75: bracket = 0.25 + 0.75·2 = 1.75',
      '',
      'tf factor B = tf·(k1+1)/(tf + k1·bracket):',
      '  k1 → 0    : B → (tf·1)/(tf) = 1   (tf saturates instantly)',
      '  k1 → ∞    : B → tf·(k1+1)/(k1·bracket) ≈ tf/bracket  (near-linear in tf)',
    ] },
  { id: 'l3-tfidf-vs-bm25', lectures: ['03'], type: 'compute',
    q: { en: 'Query {common, rare} with N=1000, df(common)=500, df(rare)=10. Doc DA stuffs the common term ten times; doc DB has common×1 + rare×1. Rank DA vs DB under TF-IDF (raw tf, idf=log₁₀(N/df)) and under BM25 — show the ranking flip and why.', ru: 'Запрос {common, rare}, N=1000, df(common)=500, df(rare)=10. Документ DA повторяет common 10 раз; DB = common×1 + rare×1. Отранжируй DA vs DB по TF-IDF (raw tf, idf=log₁₀(N/df)) и по BM25 — покажи разворот ранжирования и почему.' },
    a: { en: 'TF-IDF grows linearly in tf and rewards the term-stuffed DA: DA = 10·0.301 = 3.01 beats DB = 0.301 + 2.00 = 2.30, so TF-IDF ranks the spam doc first. BM25 flips it: its smoothed idf weights the rare term far higher (ln-idf rare = 4.5574 vs common = 0.6931) AND its tf factor saturates, so ten common occurrences only reach B = 2.17 (not 10×). DA = 0.6931·2.17 = 1.51 while DB = 0.6931·1.0 + 4.5574·1.0 = 5.25 — DB wins decisively. BM25 refuses to be gamed by repeating a frequent word.', ru: 'TF-IDF растёт линейно по tf и награждает спамный DA: DA = 10·0.301 = 3.01 обходит DB = 0.301 + 2.00 = 2.30, так что TF-IDF ставит спам-документ первым. BM25 переворачивает это: сглаженный idf даёт редкому терму куда больший вес (ln-idf rare = 4.5574 vs common = 0.6931) И tf-фактор насыщается, так что десять вхождений common дают лишь B = 2.17 (а не ×10). DA = 0.6931·2.17 = 1.51, тогда как DB = 0.6931·1.0 + 4.5574·1.0 = 5.25 — DB убедительно выигрывает. BM25 нельзя обмануть повтором частого слова.' },
    work: [
      'N=1000  df(common)=500  df(rare)=10  (assume |d|=avgdl ⇒ bracket=1)',
      '',
      'TF-IDF   idf = log10(N/df):',
      '  common = log10(1000/500) = log10(2) = 0.3010',
      '  rare   = log10(1000/10)  = log10(100) = 2.0000',
      '  DA = 10·0.3010 + 0·2.0 = 3.0103',
      '  DB =  1·0.3010 + 1·2.0 = 2.3010',
      '  TF-IDF order:  DA > DB',
      '',
      'BM25   idf = ln(1 + (N−df+0.5)/(df+0.5)):',
      '  common = ln(1 + 500.5/500.5) = ln(2)   = 0.6931',
      '  rare   = ln(1 + 990.5/10.5)  = ln(95.3) = 4.5574',
      '  B(tf=10) = 10·2.5/(10 + 1.5·1) = 25/11.5 = 2.1739',
      '  B(tf=1)  =  1·2.5/(1 + 1.5·1)  = 2.5/2.5 = 1.0000',
      '  DA = 0.6931·2.1739          = 1.5068',
      '  DB = 0.6931·1.0 + 4.5574·1.0 = 5.2505',
      '  BM25 order:  DB > DA   ← FLIPPED',
    ] },
  { id: 'l3-rrf', lectures: ['03'], type: 'compute',
    q: { en: 'RRF (k=60): fuse BM25 list [A,B,C,D] with cosine list [C,A,D,B]. Compute score(d)=Σ 1/(60+rankᵢ(d)) for every doc and give the fused order. Show how a consensus doc beats a list’s #1 that the other list buries.', ru: 'RRF (k=60): слей список BM25 [A,B,C,D] со списком cosine [C,A,D,B]. Посчитай score(d)=Σ 1/(60+rankᵢ(d)) для каждого документа и дай слитый порядок. Покажи, как консенсусный документ обходит чужого «#1», которого второй список хоронит.' },
    a: { en: 'RRF throws away raw scores and sums reciprocal ranks: score(d)=Σᵢ 1/(60+rankᵢ(d)). A is rank 1 (BM25) and rank 2 (cosine) → 0.016393 + 0.016129 = 0.032522, the highest. C is rank 3 + rank 1 → 0.032266. D ranks 4 + 3 (=0.031498) and B ranks 2 + 4 (=0.031754). Fused order: A > C > B > D. The consensus doc A wins even though cosine’s #1 was C — two solidly-high ranks sum higher than one great rank dragged down by a poor one. Ranks are calibration-free, so incomparable score scales (BM25 vs cosine) never distort the fusion.', ru: 'RRF выбрасывает сырые оценки и суммирует обратные ранги: score(d)=Σᵢ 1/(60+rankᵢ(d)). A — ранг 1 (BM25) и ранг 2 (cosine) → 0.016393 + 0.016129 = 0.032522, максимум. C — ранг 3 + ранг 1 → 0.032266. D — 4 + 3 (=0.031498), B — 2 + 4 (=0.031754). Слитый порядок: A > C > B > D. Консенсусный A выигрывает, хотя «#1» косинуса был C — два стабильно высоких ранга в сумме больше, чем один отличный, утянутый вниз слабым. Ранги не требуют калибровки, поэтому несравнимые шкалы (BM25 vs cosine) не искажают слияние.' },
    work: [
      'BM25 :  A B C D   (ranks A=1 B=2 C=3 D=4)',
      'cosine:  C A D B   (ranks C=1 A=2 D=3 B=4)',
      'k = 60',
      '',
      'A: 1/(60+1) + 1/(60+2) = 0.016393 + 0.016129 = 0.032522',
      'C: 1/(60+3) + 1/(60+1) = 0.015873 + 0.016393 = 0.032266',
      'B: 1/(60+2) + 1/(60+4) = 0.016129 + 0.015625 = 0.031754',
      'D: 1/(60+4) + 1/(60+3) = 0.015625 + 0.015873 = 0.031498',
      '',
      'fused order:  A > C > B > D',
      '(A, never #1 alone-but-consensus, beats C the cosine #1)',
    ] },
  { id: 'l3-wand', lectures: ['03'], type: 'concept',
    q: { en: 'What do WAND / BlockMax-WAND solve, and how? Sketch the skip condition with a toy upper-bound and threshold.', ru: 'Что решают WAND / BlockMax-WAND и как? Набросай условие пропуска через toy верхнюю границу и порог.' },
    a: { en: 'They make top-k retrieval effectively sublinear. Each term (WAND) or each block of a postings list (BlockMax-WAND) carries a precomputed maximum contribution. While scanning, you keep θ = the current k-th-best score; if the sum of upper bounds of the terms a candidate could match is ≤ θ, that document cannot enter the top-k, so it is skipped without a full score. BlockMax refines this to per-block max-scores, skipping whole blocks of postings at once.', ru: 'Они делают top-k поиск почти сублинейным. Каждый терм (WAND) или каждый блок постинг-листа (BlockMax-WAND) несёт предпосчитанный максимальный вклад. При сканировании держишь θ = текущий k-й лучший балл; если сумма верхних границ термов кандидата ≤ θ, документ не может попасть в top-k и пропускается без полного скоринга. BlockMax уточняет это до максимумов на блок, пропуская целые блоки постингов разом.' },
    work: [
      'maxscore(cat) = 1.8   maxscore(dog) = 0.9',
      'current top-k threshold  θ = 2.0',
      '',
      'candidate matches only {dog}:  UB = 0.9  ≤ θ=2.0  → SKIP',
      'candidate matches {cat,dog}:   UB = 1.8+0.9 = 2.7 > θ → score it',
      '',
      'BlockMax: store max per block; if blockmax(block) ≤ θ skip the whole block.',
    ] },
  { id: 'l3-rrf-why', lectures: ['03', '08'], type: 'concept',
    q: { en: 'RRF is rank-based — why is that more robust than mixing raw scores across rankers? Show what a raw-sum does when one ranker’s scale is 100× the other.', ru: 'RRF работает по рангам — почему это устойчивее, чем смешивать «сырые» оценки разных ранкеров? Покажи, что делает сырая сумма, когда шкала одного ранкера в 100× больше другой.' },
    a: { en: 'Different rankers’ score scales are incomparable — BM25 ≈ 0–30, cosine ∈ [−1,1], a logit can be anything — so a naive sum is dominated by whichever scale is larger; the small-scale ranker contributes almost nothing. RRF maps every list to ranks (1,2,3,…) before fusing, which is calibration-free and invariant to monotone score transforms, so each ranker gets a fair, bounded vote. (Min-max normalization is the alternative but is sensitive to outliers and the score distribution.)', ru: 'Шкалы оценок разных ранкеров несравнимы — BM25 ≈ 0–30, косинус ∈ [−1,1], логит — любой, — поэтому наивная сумма перекошена в сторону большей шкалы; ранкер с малой шкалой почти не влияет. RRF переводит каждый список в ранги (1,2,3,…) до слияния — это не требует калибровки и инвариантно к монотонным преобразованиям оценок, так что каждый ранкер получает честный ограниченный голос. (Min-max нормировка — альтернатива, но чувствительна к выбросам и форме распределения.)' },
    work: [
      'docX: BM25=28.0  cosine=0.20',
      'docY: BM25= 2.0  cosine=0.95',
      '',
      'raw sum:  X = 28.0+0.20 = 28.2   Y = 2.0+0.95 = 2.95   → X wins on BM25 scale alone',
      '          (cosine vote of 0.95 vs 0.20 is invisible)',
      '',
      'RRF (X rank 1/2, Y rank 2/1):',
      '  X = 1/61 + 1/62 = 0.032522',
      '  Y = 1/62 + 1/61 = 0.032522   → tie; the disagreement is fairly averaged',
    ] },
  // ───────────────────────── L3 · NEW ─────────────────────────
  { id: 'l3-bow-vectorize', lectures: ['03'], type: 'compute',
    q: { en: 'Bag-of-Words by hand: given the 3-doc corpus D1 “the cat sat”, D2 “the dog sat”, D3 “the cat and the dog”, build the sorted vocabulary, write the term-document count matrix, and express the query “cat dog” as a BoW vector over the same vocabulary.', ru: 'Bag-of-Words руками: для корпуса из 3 документов D1 «the cat sat», D2 «the dog sat», D3 «the cat and the dog» построй отсортированный словарь, выпиши матрицу «терм-документ» (счётчики) и запиши запрос «cat dog» как BoW-вектор по тому же словарю.' },
    a: { en: 'Collect every distinct token and sort: V = [and, cat, dog, sat, the], so |V| = 5 and each doc becomes a count vector in ℝ⁵. D1 = [0,1,0,1,1], D2 = [0,0,1,1,1], D3 = [1,1,1,0,2] (note “the” appears twice in D3). The query “cat dog” is just another vector over V: [0,1,1,0,0]. BoW discards word order entirely — “cat dog” and “dog cat” map to the same vector — and the high count of the stopword “the” carries no topic signal, which is exactly what IDF later down-weights.', ru: 'Собери все уникальные токены и отсортируй: V = [and, cat, dog, sat, the], значит |V| = 5 и каждый документ — вектор счётчиков в ℝ⁵. D1 = [0,1,0,1,1], D2 = [0,0,1,1,1], D3 = [1,1,1,0,2] (учти, что «the» в D3 дважды). Запрос «cat dog» — такой же вектор по V: [0,1,1,0,0]. BoW полностью теряет порядок слов — «cat dog» и «dog cat» дают один вектор — а большой счётчик стоп-слова «the» не несёт тематического сигнала, что и занижает IDF позже.' },
    work: [
      'tokens: D1{the,cat,sat} D2{the,dog,sat} D3{the,cat,and,the,dog}',
      'vocabulary (sorted) V = [ and, cat, dog, sat, the ]   |V| = 5',
      '',
      '          and  cat  dog  sat  the',
      'D1         0    1    0    1    1',
      'D2         0    0    1    1    1',
      'D3         1    1    1    0    2',
      '',
      'query "cat dog"  →  [ 0, 1, 1, 0, 0 ]',
      '("dog cat" would give the SAME vector — order is lost)',
    ] },
  { id: 'l3-boolean-phrase', lectures: ['03'], type: 'compute',
    q: { en: 'Boolean & phrase queries on a tiny inverted index. Postings: cat→[1,2,4,5], dog→[2,4,5], bird→[1,5]. Evaluate (cat AND dog), (cat OR bird), (cat AND NOT dog), and (cat AND dog) AND NOT bird. Then, with positional postings machine→D7:[2,9], learning→D7:[3,15], decide whether the phrase “machine learning” matches D7.', ru: 'Boolean- и фразовые запросы по мини-инвертированному индексу. Постинги: cat→[1,2,4,5], dog→[2,4,5], bird→[1,5]. Вычисли (cat AND dog), (cat OR bird), (cat AND NOT dog) и (cat AND dog) AND NOT bird. Затем по позиционным постингам machine→D7:[2,9], learning→D7:[3,15] реши, есть ли в D7 фраза «machine learning».' },
    a: { en: 'Boolean operators are set operations on doc-id lists: AND = intersection, OR = union, NOT = difference. cat AND dog = {1,2,4,5}∩{2,4,5} = [2,4,5]; cat OR bird = {1,2,4,5}∪{1,5} = [1,2,4,5]; cat AND NOT dog = {1,2,4,5}∖{2,4,5} = [1]; (cat AND dog) AND NOT bird = {2,4,5}∖{1,5} = [2,4]. For the phrase, doc-level AND first confirms both terms are in D7; then walk the position lists for offsets exactly one apart: machine@2, learning@3 gives 3−2=1 → a hit, while machine@9 vs learning@15 has gap 6 → not adjacent. So “machine learning” matches D7 (once). Generalising the gap to ≤ k gives proximity search.', ru: 'Булевы операторы — это операции над множествами doc-id: AND = пересечение, OR = объединение, NOT = разность. cat AND dog = {1,2,4,5}∩{2,4,5} = [2,4,5]; cat OR bird = {1,2,4,5}∪{1,5} = [1,2,4,5]; cat AND NOT dog = {1,2,4,5}∖{2,4,5} = [1]; (cat AND dog) AND NOT bird = {2,4,5}∖{1,5} = [2,4]. Для фразы сперва doc-level AND подтверждает оба терма в D7; затем проходим по позициям, ища смещения ровно на 1: machine@2, learning@3 даёт 3−2=1 → совпадение, тогда как machine@9 vs learning@15 — зазор 6 → не смежно. Значит «machine learning» есть в D7 (один раз). Обобщение зазора до ≤ k даёт поиск по близости.' },
    work: [
      'cat=[1,2,4,5]  dog=[2,4,5]  bird=[1,5]',
      '',
      'cat AND dog            = {1,2,4,5} ∩ {2,4,5} = [2, 4, 5]',
      'cat OR  bird           = {1,2,4,5} ∪ {1,5}   = [1, 2, 4, 5]',
      'cat AND NOT dog        = {1,2,4,5} \\ {2,4,5} = [1]',
      '(cat AND dog) AND NOT bird = {2,4,5} \\ {1,5} = [2, 4]',
      '',
      'phrase "machine learning" in D7:',
      '  machine @ [2, 9]   learning @ [3, 15]',
      '  need p_learning − p_machine = 1',
      '  3 − 2 = 1  ✓ hit      15 − 9 = 6  ✗',
      '  → matches D7 (one occurrence)',
    ] },
  { id: 'l3-pagerank-step', lectures: ['03'], type: 'compute',
    q: { en: 'One power-iteration step of PageRank (d=0.85) on the 4-edge graph A→B, A→C, B→C, C→A. Start uniform v₀=(⅓,⅓,⅓), tabulate out-degrees, apply PR(p)=(1−d)/n + d·Σ_(q→p) PR(q)/outdeg(q), and give the updated rank vector.', ru: 'Один шаг power-iteration PageRank (d=0.85) на графе из 4 рёбер A→B, A→C, B→C, C→A. Старт равномерный v₀=(⅓,⅓,⅓), выпиши out-degree, примени PR(p)=(1−d)/n + d·Σ_(q→p) PR(q)/outdeg(q) и дай обновлённый вектор рангов.' },
    a: { en: 'Out-degrees: A=2 (→B,→C), B=1 (→C), C=1 (→A). In-links: A←C, B←A, C←A,B. The teleport base is (1−0.85)/3 = 0.05. A gets all of C’s vote (C/1); B gets half of A’s (A/2, since A links to two pages); C gets half of A’s plus all of B’s. With v₀ = ⅓ each: PR₁(A)=0.05+0.85·0.3333=0.3333, PR₁(B)=0.05+0.85·0.1667=0.1917, PR₁(C)=0.05+0.85·(0.1667+0.3333)=0.4750. The vector sums to 1.0 and C — the only node with two in-links — already leads after a single step.', ru: 'Out-degree: A=2 (→B,→C), B=1 (→C), C=1 (→A). In-links: A←C, B←A, C←A,B. База телепорта (1−0.85)/3 = 0.05. A получает весь голос C (C/1); B — половину голоса A (A/2, ведь A ссылается на две страницы); C — половину A плюс весь B. При v₀ = ⅓ каждый: PR₁(A)=0.05+0.85·0.3333=0.3333, PR₁(B)=0.05+0.85·0.1667=0.1917, PR₁(C)=0.05+0.85·(0.1667+0.3333)=0.4750. Вектор суммируется в 1.0, и C — единственный узел с двумя in-links — уже лидирует после одного шага.' },
    work: [
      'edges: A→B, A→C, B→C, C→A     d = 0.85,  n = 3',
      'outdeg: A=2,  B=1,  C=1',
      'in-links: A←C ;  B←A ;  C←A,B',
      'base = (1−d)/n = 0.15/3 = 0.05',
      'v0 = (1/3, 1/3, 1/3) = (0.3333, 0.3333, 0.3333)',
      '',
      'PR1(A) = 0.05 + 0.85·(PR0(C)/1)            = 0.05 + 0.85·0.3333 = 0.3333',
      'PR1(B) = 0.05 + 0.85·(PR0(A)/2)            = 0.05 + 0.85·0.1667 = 0.1917',
      'PR1(C) = 0.05 + 0.85·(PR0(A)/2 + PR0(B)/1) = 0.05 + 0.85·0.5000 = 0.4750',
      '',
      'v1 = (0.3333, 0.1917, 0.4750)   Σ = 1.0    C leads (2 in-links)',
    ] },
  { id: 'l3-compression', lectures: ['03'], type: 'concept',
    q: { en: 'Why do postings lists compress so well? Explain delta/gap encoding + variable-byte, and show the byte saving on docIDs [3, 8, 12, 30].', ru: 'Почему постинг-листы так хорошо сжимаются? Объясни delta/gap-кодирование + variable-byte и покажи экономию байт на docID [3, 8, 12, 30].' },
    a: { en: 'Postings dominate index size, and the doc-ids in a list are sorted, so instead of storing absolute ids you store the gaps between successive ids — these are small, and small numbers need few bits. Variable-byte coding packs each gap into bytes of 7 data bits + 1 continuation bit, so any value 0–127 fits in a single byte. On [3,8,12,30] the gaps are [3,5,4,18], all < 128, so 4 bytes instead of 4×4 = 16 raw → a 4× reduction. A smaller index stays in cache and cuts I/O, the real query-time bottleneck. (Real engines use PForDelta / Simple-9 / Roaring, but the gap-then-encode idea is identical.)', ru: 'Постинги доминируют в размере индекса, а doc-id в списке отсортированы, поэтому вместо абсолютных id хранят разности (gaps) между соседними — они малы, а малым числам нужно мало бит. Variable-byte упаковывает каждый gap в байты по 7 бит данных + 1 бит продолжения, так что любое значение 0–127 влезает в один байт. На [3,8,12,30] gaps = [3,5,4,18], все < 128, значит 4 байта вместо 4×4 = 16 сырых → сокращение в 4×. Меньший индекс остаётся в кэше и режет I/O — реальное узкое место на запросе. (В проде PForDelta / Simple-9 / Roaring, но идея «gap, потом кодируй» та же.)' },
    work: [
      'docIDs [3, 8, 12, 30]  raw = 4 × 4-byte int = 16 bytes',
      '',
      'gaps  = [3, 8−3, 12−8, 30−12] = [3, 5, 4, 18]   (all small)',
      '',
      'varbyte: 1 byte = 1 continuation bit + 7 data bits → holds 0–127',
      'max(gaps) = 18 < 128  ⇒ each gap = 1 byte ⇒ 4 bytes total',
      '',
      '16 bytes → 4 bytes  =  4× compression',
    ] },
  // ───────────────────────── L4 · DEEPENED ─────────────────────────
  { id: 'l4-graded', lectures: ['04'], type: 'concept',
    q: { en: 'Binary vs graded relevance — which metrics need graded qrels and why? Show on one ranking how the gain 2^rel−1 separates a “highly relevant” hit from a “mildly relevant” one.', ru: 'Binary vs graded релевантность — каким метрикам нужны градуированные qrels и почему? Покажи на одном ранжировании, как gain 2^rel−1 разводит «очень релевантный» и «слегка релевантный» результаты.' },
    a: { en: 'Precision, Recall, MRR and MAP collapse every judgment to relevant/not, so they only need binary qrels and cannot tell a perfect hit from a merely okay one. nDCG needs graded judgments because its gain function rewards higher grades super-linearly — the exponential gain 2^rel−1 maps grades 0/1/2/3 to gains 0/1/3/7, so a grade-3 doc is worth 7× a grade-1 doc, not 3×. That is exactly what lets nDCG distinguish “put the perfect answer first” from “put a so-so answer first.”', ru: 'Precision, Recall, MRR и MAP сводят каждую оценку к «релевантен/нет», поэтому им нужны лишь бинарные qrels и они не отличают идеальный результат от просто приемлемого. nDCG нужны градуированные оценки, ведь его gain награждает высокие оценки сверхлинейно — экспоненциальный gain 2^rel−1 переводит оценки 0/1/2/3 в выигрыши 0/1/3/7, так что документ оценки 3 стоит 7× документа оценки 1, а не 3×. Именно это позволяет nDCG различать «идеальный ответ первым» и «средний ответ первым».' },
    work: [
      'grade rel :  0    1    2    3',
      'linear gain (=rel)        : 0    1    2    3',
      'exponential gain 2^rel−1  : 0    1    3    7',
      '',
      'so a grade-3 hit is worth 7×, not 3×, a grade-1 hit',
      'binary metrics (P,R,MRR,MAP) would score both as just "relevant=1"',
      '(scale shown 0/1/2/3; this course usually grades 0/1/3 — same exponential idea)',
    ] },
  { id: 'l4-pr-mrr', lectures: ['04'], type: 'compute',
    q: { en: 'For the ranking with relevance pattern [1,0,1,1,0] and 4 relevant docs total (one not retrieved), compute P@3, P@5, R@5, and the reciprocal rank for MRR.', ru: 'Для ранжирования с паттерном релевантности [1,0,1,1,0] и 4 релевантными документами всего (один не извлечён) посчитай P@3, P@5, R@5 и обратный ранг для MRR.' },
    a: { en: 'P@k = (#relevant in top-k)/k. Top-3 has 2 relevant → P@3 = 2/3 ≈ 0.667; top-5 has 3 relevant → P@5 = 3/5 = 0.6. R@k = (#relevant in top-k)/(total relevant). With 4 relevant overall, R@5 = 3/4 = 0.75 — the fourth relevant doc was never retrieved, so recall is capped below 1. The reciprocal rank is 1/(rank of first relevant); the first hit is at rank 1, so RR = 1/1 = 1.0, and MRR is the mean of RR across queries (here a single query → 1.0).', ru: 'P@k = (#релевантных в top-k)/k. В top-3 — 2 релевантных → P@3 = 2/3 ≈ 0.667; в top-5 — 3 → P@5 = 3/5 = 0.6. R@k = (#релевантных в top-k)/(всего релевантных). При 4 релевантных всего R@5 = 3/4 = 0.75 — четвёртый релевантный не был извлечён, и recall ограничен ниже 1. Обратный ранг = 1/(ранг первого релевантного); первый хит на ранге 1, значит RR = 1/1 = 1.0, а MRR — среднее RR по запросам (здесь один запрос → 1.0).' },
    work: [
      'ranking relevance = [1, 0, 1, 1, 0]      total relevant R = 4',
      '',
      'P@3 = (#rel in top-3)/3 = 2/3 = 0.6667',
      'P@5 = (#rel in top-5)/5 = 3/5 = 0.6000',
      'R@5 = (#rel in top-5)/R = 3/4 = 0.7500   (4th relevant never retrieved)',
      '',
      'first relevant at rank 1  →  RR = 1/1 = 1.0',
      'MRR = mean of RR over queries',
    ] },
  { id: 'l4-ndcg', lectures: ['04'], type: 'compute',
    q: { en: 'Compute nDCG@4 by hand for graded ranking [2,0,3,1] using exponential gain 2^rel−1 and discount log₂(i+1): DCG → IDCG (ideal order) → ratio.', ru: 'Посчитай nDCG@4 руками для градуированного ранжирования [2,0,3,1] с экспоненциальным gain 2^rel−1 и дисконтом log₂(i+1): DCG → IDCG (идеальный порядок) → отношение.' },
    a: { en: 'DCG = Σᵢ (2^relᵢ−1)/log₂(i+1). For [2,0,3,1]: rank 1 gives 3/1 = 3.0, rank 2 gives 0, rank 3 gives 7/2 = 3.5, rank 4 gives 1/2.3219 = 0.4307, so DCG = 6.9307. The ideal ranking sorts grades descending [3,2,1,0]: IDCG = 7/1 + 3/1.585 + 1/2 + 0 = 7.0 + 1.8928 + 0.5 = 9.3928. nDCG = 6.9307/9.3928 ≈ 0.7379 — a single comparable score in [0,1]. It is below 1 mainly because the best doc (grade 3) sits at rank 3 instead of rank 1, where the discount is gentlest.', ru: 'DCG = Σᵢ (2^relᵢ−1)/log₂(i+1). Для [2,0,3,1]: ранг 1 даёт 3/1 = 3.0, ранг 2 — 0, ранг 3 — 7/2 = 3.5, ранг 4 — 1/2.3219 = 0.4307, итого DCG = 6.9307. Идеальное ранжирование сортирует оценки по убыванию [3,2,1,0]: IDCG = 7/1 + 3/1.585 + 1/2 + 0 = 7.0 + 1.8928 + 0.5 = 9.3928. nDCG = 6.9307/9.3928 ≈ 0.7379 — одно сопоставимое число в [0,1]. Оно ниже 1 в основном потому, что лучший документ (оценка 3) стоит на ранге 3, а не на ранге 1, где дисконт мягче всего.' },
    work: [
      'grades g = [2, 0, 3, 1]    gain = 2^rel − 1,   discount = log2(i+1)',
      '',
      'rank 1: (2^2−1)/log2(2) = 3/1.0000 = 3.0000',
      'rank 2: (2^0−1)/log2(3) = 0/1.5850 = 0.0000',
      'rank 3: (2^3−1)/log2(4) = 7/2.0000 = 3.5000',
      'rank 4: (2^1−1)/log2(5) = 1/2.3219 = 0.4307',
      'DCG = 3.0000 + 0 + 3.5000 + 0.4307 = 6.9307',
      '',
      'ideal order (sort grades desc) = [3, 2, 1, 0]:',
      'rank 1: 7/1.0000 = 7.0000',
      'rank 2: 3/1.5850 = 1.8928',
      'rank 3: 1/2.0000 = 0.5000',
      'rank 4: 0/2.3219 = 0.0000',
      'IDCG = 9.3928',
      '',
      'nDCG = DCG/IDCG = 6.9307/9.3928 = 0.7379',
      '(grades on the 0–3 scale, grade 2 included; the deck examples often use {0,1,3})',
    ] },
  { id: 'l4-map', lectures: ['04'], type: 'compute',
    q: { en: 'Compute AP for two queries and then MAP. Q1 = [0,1,0,1,0,1,0,1], Q2 = [1,0,1,1,0,0,1,0], each with 4 relevant docs. AP averages P@k at each relevant-doc rank.', ru: 'Посчитай AP для двух запросов и затем MAP. Q1 = [0,1,0,1,0,1,0,1], Q2 = [1,0,1,1,0,0,1,0], у каждого 4 релевантных. AP усредняет P@k на каждом ранге релевантного документа.' },
    a: { en: 'AP = (1/R)·Σ over relevant ranks r of P@r. Q1’s hits are at ranks 2,4,6,8, where precisions are 1/2, 2/4, 3/6, 4/8 — all exactly 0.5 — so AP₁ = (0.5·4)/4 = 0.5. Q2’s hits are front-loaded at ranks 1,3,4,7 with precisions 1/1, 2/3, 3/4, 4/7 = 1.0, 0.6667, 0.75, 0.5714, giving AP₂ = (1.0+0.6667+0.75+0.5714)/4 = 0.747. MAP is the mean of the per-query APs: (0.5+0.747)/2 = 0.6235 — equal to neither AP, and AP rewards placing relevant docs early (Q2 > Q1 despite the same count).', ru: 'AP = (1/R)·Σ по рангам релевантных r от P@r. Хиты Q1 на рангах 2,4,6,8, где precision = 1/2, 2/4, 3/6, 4/8 — все ровно 0.5 — значит AP₁ = (0.5·4)/4 = 0.5. Хиты Q2 сдвинуты вперёд на ранги 1,3,4,7 с precision 1/1, 2/3, 3/4, 4/7 = 1.0, 0.6667, 0.75, 0.5714, дают AP₂ = (1.0+0.6667+0.75+0.5714)/4 = 0.747. MAP — среднее AP по запросам: (0.5+0.747)/2 = 0.6235 — не равно ни одному AP, и AP награждает раннее размещение релевантных (Q2 > Q1 при том же числе).' },
    work: [
      'Q1 = [0,1,0,1,0,1,0,1]   R = 4   hits at ranks 2,4,6,8',
      '  P@2=1/2=0.5  P@4=2/4=0.5  P@6=3/6=0.5  P@8=4/8=0.5',
      '  AP1 = (0.5+0.5+0.5+0.5)/4 = 0.5',
      '',
      'Q2 = [1,0,1,1,0,0,1,0]   R = 4   hits at ranks 1,3,4,7',
      '  P@1=1/1=1.0  P@3=2/3=0.6667  P@4=3/4=0.75  P@7=4/7=0.5714',
      '  AP2 = (1.0+0.6667+0.75+0.5714)/4 = 0.747',
      '',
      'MAP = (AP1 + AP2)/2 = (0.5 + 0.747)/2 = 0.6235',
    ] },
  { id: 'l4-significance', lectures: ['04'], type: 'concept',
    q: { en: 'You beat BM25 by +2% nDCG — is it real? Which test, what does p mean, and how does per-query variance decide it? Sketch a paired comparison on a few queries.', ru: 'Ты обошёл BM25 на +2% nDCG — это реально? Какой тест, что значит p, и как per-query дисперсия решает вопрос? Набросай парное сравнение на нескольких запросах.' },
    a: { en: 'Use a paired significance test on the per-query scores. The most defensible in IR is the randomization / permutation test (Smucker, Allan & Carterette) — it assumes almost nothing about the score distribution; the paired t-test and the Wilcoxon signed-rank test are common, faster approximations. They are paired because each query runs through both systems, so you analyse the per-query differences, which removes query-difficulty noise. p is the probability of seeing a difference this large (or larger) if the two systems were truly equal; small p (e.g. < 0.05) means the gap is unlikely to be chance. The verdict hinges on variance: a +2% mean with tiny, consistently-positive per-query deltas is significant, but the same +2% with deltas swinging ±20% across queries is not. Testing many variants inflates false positives — correct for it.', ru: 'Парный тест значимости на per-query оценках. Самый защищённый в IR — рандомизационный / перестановочный тест (Smucker, Allan & Carterette), он почти ничего не предполагает о распределении; парный t-тест и Wilcoxon signed-rank — частые более быстрые приближения. Парный, потому что каждый запрос прогоняется через обе системы, и анализируются per-query разности, что убирает шум сложности запроса. p — вероятность увидеть такую (или большую) разницу, если системы на деле равны; малое p (напр. < 0.05) значит, что разрыв вряд ли случаен. Вердикт зависит от дисперсии: +2% при малых стабильно положительных дельтах значим, но те же +2% при дельтах ±20% по запросам — нет. Проверка многих вариантов раздувает ложные срабатывания — нужна поправка.' },
    work: [
      'per-query nDCG (new − BM25):  +0.03  +0.01  +0.02  +0.02  +0.02',
      '  mean Δ = +0.02   sd ≈ 0.007   → tight & all positive → likely significant',
      '',
      'contrast:  +0.22  −0.18  +0.20  −0.16  +0.02',
      '  mean Δ = +0.02   sd ≈ 0.20    → huge swings → NOT significant',
      '',
      'randomization/permutation (preferred · Smucker–Allan–Carterette):',
      '  shuffle which system each query is credited to, many times;',
      '  p = fraction of shuffles with |mean Δ| ≥ the observed |mean Δ|',
      'paired t:  t = mean(Δ) / (sd/√n);   small p ⇒ gap unlikely under H0 (systems equal)',
      'Wilcoxon signed-rank: ranks of |Δ|, no normality assumption',
    ] },
  { id: 'l4-online', lectures: ['04'], type: 'concept',
    q: { en: 'Why do offline metrics + click logs mislead (position bias), and what does an A/B test add? What does interleaving / IPS fix?', ru: 'Почему оффлайн-метрики и клик-логи вводят в заблуждение (position bias) и что добавляет A/B? Что чинят interleaving / IPS?' },
    a: { en: 'Clicks are biased by rank: a document gets clicked partly because it sits at the top, not only because it is the best answer, so click-through is not ground truth and offline metrics computed from logged clicks inherit that bias. An A/B test measures real user behaviour under each system on live traffic, so it captures actual satisfaction rather than a proxy. Interleaving blends two rankers’ results into one list and attributes each click to the ranker that contributed the item — far more sensitive per user than A/B. Inverse-Propensity Scoring (IPS) reweights each click by 1/P(examined at that rank) to debias the logs directly.', ru: 'Клики смещены рангом: документ кликают отчасти потому, что он наверху, а не только потому, что он лучший ответ, поэтому CTR — не истина, и оффлайн-метрики по логам наследуют это смещение. A/B измеряет реальное поведение под каждой системой на живом трафике и ловит фактическое удовлетворение, а не прокси. Interleaving смешивает результаты двух ранкеров в один список и приписывает каждый клик ранкеру, давшему элемент — куда чувствительнее на пользователя, чем A/B. Inverse-Propensity Scoring (IPS) перевзвешивает каждый клик на 1/P(просмотрен на этом ранге), убирая смещение прямо в логах.' },
    work: [
      'logged CTR by rank:  r1=8%  r2=5%  r3=3% ...  (decays even for equally-relevant docs)',
      '→ a doc clicked at r1 may just be top, not best  (position bias)',
      '',
      'IPS: weight click by 1/P(examine | rank).',
      '  click at r1, P=0.8 → weight 1/0.8 = 1.25',
      '  click at r3, P=0.3 → weight 1/0.3 = 3.33   (rare-examination clicks count more)',
      '',
      'interleaving: merge A,B into one list; click → credit to the source ranker',
    ] },
  // ───────────────────────── L4 · NEW ─────────────────────────
  { id: 'l4-f1', lectures: ['04'], type: 'compute',
    q: { en: 'Compute F1 from Precision and Recall the harmonic-mean way, and show why it differs from the arithmetic mean. Use a retrieval with 3 relevant in the top-5 and 6 relevant overall.', ru: 'Посчитай F1 из Precision и Recall как гармоническое среднее и покажи, чем оно отличается от арифметического. Возьми выдачу с 3 релевантными в top-5 и 6 релевантными всего.' },
    a: { en: 'P = (#relevant in top-k)/k = 3/5 = 0.6; R = (#relevant in top-k)/(total relevant) = 3/6 = 0.5. F1 = 2PR/(P+R) = 2·0.6·0.5/(0.6+0.5) = 0.6/1.1 ≈ 0.545. The harmonic mean (0.545) sits below the arithmetic mean (0.55) and, crucially, is dominated by the smaller of the two — so a system that maxes one and tanks the other is punished. As a sanity check, with P=0.6, R=0.4 you get F1 = 2·0.24/1.0 = 0.48 < arithmetic mean 0.5; the gap grows as P and R diverge, which is exactly why F1 refuses to reward imbalance.', ru: 'P = (#релевантных в top-k)/k = 3/5 = 0.6; R = (#релевантных в top-k)/(всего релевантных) = 3/6 = 0.5. F1 = 2PR/(P+R) = 2·0.6·0.5/(0.6+0.5) = 0.6/1.1 ≈ 0.545. Гармоническое среднее (0.545) ниже арифметического (0.55) и, что важно, тяготеет к меньшему из двух — система, максимизирующая одно и проваливающая другое, штрафуется. Для проверки: при P=0.6, R=0.4 получим F1 = 2·0.24/1.0 = 0.48 < арифм. среднего 0.5; разрыв растёт с расхождением P и R — поэтому F1 не награждает дисбаланс.' },
    work: [
      'top-5: 3 relevant retrieved;  total relevant = 6',
      'P = 3/5 = 0.6        R = 3/6 = 0.5',
      '',
      'F1 = 2PR/(P+R) = 2·(0.6·0.5)/(0.6+0.5) = 2·0.30/1.1 = 0.60/1.1 = 0.5455',
      'arithmetic mean = (0.6+0.5)/2 = 0.55      → F1 < AM',
      '',
      'imbalance check: P=0.6, R=0.4',
      '  F1 = 2·0.24/1.0 = 0.48   < AM = 0.50   (harmonic mean leans to the smaller)',
    ] },
  { id: 'l4-kappa', lectures: ['04'], type: 'compute',
    q: { en: 'Cohen’s κ: explain why raw agreement is misleading and compute κ for two annotators who judge 100 docs as relevant/non — both-relevant 40, both-non 30, disagree 15+15.', ru: 'Cohen’s κ: объясни, почему сырое согласие обманчиво, и посчитай κ для двух аннотаторов, оценивших 100 документов как rel/non — оба rel 40, оба non 30, расхождения 15+15.' },
    a: { en: 'Raw agreement counts the chance overlap two annotators get just from their label rates, so a κ correction subtracts it: κ = (pₒ − pₑ)/(1 − pₑ). Here observed agreement pₒ = (40+30)/100 = 0.70. Each annotator labelled 55/100 relevant, so chance agreement pₑ = 0.55·0.55 + 0.45·0.45 = 0.3025 + 0.2025 = 0.505. Then κ = (0.70 − 0.505)/(1 − 0.505) = 0.195/0.495 ≈ 0.394 — only “fair” agreement on the Landis–Koch scale (0.21–0.40 = fair) despite a 70% raw match, because much of that match is expected by chance. Low κ means the qrels are noisy and cap the resolution of any metric built on them.', ru: 'Сырое согласие учитывает случайное совпадение, которое два аннотатора получают просто из своих долей меток, поэтому поправка κ его вычитает: κ = (pₒ − pₑ)/(1 − pₑ). Здесь наблюдаемое согласие pₒ = (40+30)/100 = 0.70. Каждый разметил 55/100 как rel, значит случайное согласие pₑ = 0.55·0.55 + 0.45·0.45 = 0.3025 + 0.2025 = 0.505. Тогда κ = (0.70 − 0.505)/(1 − 0.505) = 0.195/0.495 ≈ 0.394 — лишь «удовлетворительное» согласие по шкале Landis–Koch (0.21–0.40 = «удовлетворительно») при 70% сыром совпадении, ведь многое из него ожидаемо случайно. Низкий κ значит, что qrels шумные и ограничивают разрешение любой метрики на них.' },
    work: [
      'confusion (100 docs):  both-rel=40  both-non=30  A-rel/B-non=15  A-non/B-rel=15',
      '',
      'po = (40 + 30)/100 = 0.70                 (observed agreement)',
      'marginals: A rel = (40+15)/100 = 0.55 ;  B rel = (40+15)/100 = 0.55',
      '           A non = 0.45 ;  B non = 0.45',
      'pe = P(both rel by chance) + P(both non by chance)',
      '   = 0.55·0.55 + 0.45·0.45 = 0.3025 + 0.2025 = 0.505',
      '',
      'kappa = (po − pe)/(1 − pe) = (0.70 − 0.505)/(1 − 0.505)',
      '      = 0.195 / 0.495 = 0.394   (Landis–Koch 0.21–0.40 = "fair"; >0.6 substantial)',
    ] },
  { id: 'l4-multiple-comparisons', lectures: ['04'], type: 'concept',
    q: { en: 'Why does testing many systems inflate false positives, and how does the Bonferroni correction fix it? Quantify both for 20 tests at α=0.05.', ru: 'Почему проверка многих систем раздувает ложные срабатывания и как чинит поправка Bonferroni? Посчитай оба для 20 тестов при α=0.05.' },
    a: { en: 'At α=0.05 each individual test has a 5% chance of a false positive even when no system is truly better. Run m independent tests and the chance of at least one false alarm is 1 − (1−α)^m; for m=20 that is 1 − 0.95²⁰ ≈ 0.64 — you expect about one bogus “winner.” Cherry-picking the single variant that hit p<0.05 is therefore shipping noise. Bonferroni controls the family-wise error rate by testing each hypothesis at the stricter threshold α/m = 0.05/20 = 0.0025, so the overall false-positive rate stays ≤ 0.05. (Benjamini–Hochberg is a more powerful alternative that controls the false-discovery rate; the cleanest defence is to confirm the winner on a fresh query set or an online A/B test.)', ru: 'При α=0.05 у каждого отдельного теста 5% шанс ложного срабатывания, даже если ни одна система не лучше. Запусти m независимых тестов — и шанс хотя бы одной ложной тревоги равен 1 − (1−α)^m; для m=20 это 1 − 0.95²⁰ ≈ 0.64 — ждёшь примерно одного липового «победителя». Выбор единственного варианта с p<0.05 — это отгрузка шума. Bonferroni контролирует family-wise error rate, проверяя каждую гипотезу по более строгому порогу α/m = 0.05/20 = 0.0025, и общий уровень ложных срабатываний остаётся ≤ 0.05. (Benjamini–Hochberg — более мощная альтернатива, контролирует false-discovery rate; чистейшая защита — подтвердить победителя на свежем наборе запросов или в онлайн A/B.)' },
    work: [
      'm = 20 tests,  α = 0.05',
      '',
      'P(≥1 false positive, uncorrected) = 1 − (1−α)^m',
      '  = 1 − 0.95^20 = 1 − 0.3585 = 0.6415   (~1 expected false "winner")',
      '',
      'Bonferroni: test each at α/m = 0.05/20 = 0.0025',
      '  → family-wise error rate held ≤ 0.05',
      '',
      'better still: confirm the winner on a FRESH query set or an online A/B test',
    ] },

// ═══════════════════════════ L5 · The Map of Meaning ═══════════════════════════

  // ── DEEPENED: lexical gap / equidistance (existing id) ──
  { id: 'l5-lexgap', lectures: ['05'], type: 'compute',
    q: { en: 'One-hot vectors by hand: build them for a 3-word vocabulary {cat, dog, airplane}. Show every distinct pair has dot product 0 (orthogonal) and the SAME L2 distance — so the representation has no notion of meaning.', ru: 'One-hot векторы руками: построй их для словаря из 3 слов {cat, dog, airplane}. Покажи, что любая пара разных слов имеет скалярное произведение 0 (ортогональны) и ОДИНАКОВОЕ L2-расстояние — у представления нет понятия смысла.' },
    a: { en: 'Each word is its own axis, so distinct words share no nonzero dimension: every pairwise dot product is 0 and cos = 0, and every pair sits at the same Euclidean distance √2. cat is exactly as far from dog as from airplane — there is no geometry of meaning. This is the lexical gap that motivates dense embeddings: a string matcher (one-hot / BM25) treats couch and sofa as orthogonal too.', ru: 'Каждое слово — собственная ось, поэтому разные слова не делят ни одного ненулевого измерения: каждое попарное скалярное произведение = 0 и cos = 0, а любая пара — на одинаковом евклидовом расстоянии √2. cat ровно так же далёк от dog, как от airplane — геометрии смысла нет. Это и есть lexical gap, мотивирующий плотные эмбеддинги: строковое сопоставление (one-hot / BM25) считает couch и sofa тоже ортогональными.' },
    work: [
      'V = {cat, dog, airplane},  |V| = 3',
      'cat      = [1, 0, 0]',
      'dog      = [0, 1, 0]',
      'airplane = [0, 0, 1]',
      '',
      'dot products (overlap):',
      '  cat·dog      = 1·0 + 0·1 + 0·0 = 0',
      '  cat·airplane = 1·0 + 0·0 + 0·1 = 0',
      '  dog·airplane = 0                = 0',
      'cos = dot / (‖·‖‖·‖) = 0 / (1·1) = 0   for every distinct pair',
      '',
      'L2 distance ‖a − b‖:',
      '  cat − dog      = [1,−1, 0] → √(1+1+0) = √2 ≈ 1.414',
      '  cat − airplane = [1, 0,−1] → √(1+0+1) = √2 ≈ 1.414',
      '  dog − airplane = [0, 1,−1] → √2',
      '',
      '⇒ all off-diagonal dots = 0, all pair-distances = √2 (equidistant)',
      '⇒ no «near in meaning»; |V| words need |V| orthogonal axes',
    ] },

  // ── DEEPENED: skip-gram objective formulated mathematically (existing id) ──
  { id: 'l5-skipgram', lectures: ['05'], type: 'compute',
    q: { en: 'word2vec skip-gram objective, written mathematically: maximize Σ log P(context | centre) with P a softmax over |V|. Why is the full softmax intractable, and write the negative-sampling loss that replaces it.', ru: 'Объектив skip-gram word2vec, записанный математически: максимизируем Σ log P(контекст | центр), где P — softmax по |V|. Почему полный softmax неподъёмен и какой лосс negative sampling его заменяет?' },
    a: { en: 'Skip-gram slides a window and predicts context words from the centre: maximize the log-likelihood Σ log P(c | w), with P(c|w) = softmax of the dot score uᵀc·vw over the whole vocabulary. The denominator sums exp(uᵀc′·vw) over ALL |V|≈10⁶ words on every single update — O(|V|) per step, intractable. Negative sampling replaces the multi-class softmax with a binary logistic test: push the true pair up (σ→1) and a handful of k random «negative» contexts down (σ→0), drawn from Pn ∝ freq^(3/4). Cost drops from O(|V|) to O(k), about five orders of magnitude.', ru: 'Skip-gram двигает окно и предсказывает слова контекста из центра: максимизируем лог-правдоподобие Σ log P(c | w), где P(c|w) = softmax от скалярного скора uᵀc·vw по всему словарю. Знаменатель суммирует exp(uᵀc′·vw) по ВСЕМ |V|≈10⁶ словам на каждом шаге — O(|V|) за шаг, неподъёмно. Negative sampling заменяет многоклассовый softmax бинарным логистическим тестом: тянем истинную пару вверх (σ→1), а несколько k случайных «негативных» контекстов вниз (σ→0), сэмплируя из Pn ∝ freq^(3/4). Стоимость падает с O(|V|) до O(k), примерно пять порядков.' },
    work: [
      'each word has TWO vectors: centre v_w, context u_c',
      '',
      'objective (maximise log-likelihood over corpus):',
      '  max Σ_w Σ_(−m≤j≤m, j≠0) log P(w_(t+j) | w_t)',
      '',
      'softmax over the whole vocabulary:',
      '              exp(u_c · v_w)',
      '  P(c|w) = ─────────────────────────',
      '            Σ_(c′∈V) exp(u_c′ · v_w)      ← sums over ALL |V| words',
      '',
      'cost: denominator = |V| ≈ 10⁶ dot products PER update → O(|V|) → intractable',
      '',
      'negative-sampling loss (per (w,c) pair, k negatives c_i ∼ Pn):',
      '  L = − log σ(u_c · v_w)  −  Σ_(i=1)^(k) log σ(−u_(c_i) · v_w)',
      '      └ pull true pair up ┘  └ push k random negatives down ┘',
      '  σ(z) = 1/(1+e^(−z)),   Pn(w) ∝ freq(w)^(3/4),   k = 5…20',
      '  cost: O(k) per step  (≪ O(|V|))',
    ] },

  // ── DEEPENED: king − man + woman analogy with toy vectors + cosine (existing id) ──
  { id: 'l5-analogy', lectures: ['05'], type: 'compute',
    q: { en: 'Verify king − man + woman ≈ queen with toy 2-D vectors: compute r = king − man + woman, then cosine of r against each candidate and show queen wins. (Lecture GloVe-50d: cos(king−man+woman, queen) = 0.861.)', ru: 'Проверь king − man + woman ≈ queen на toy 2-D векторах: посчитай r = king − man + woman, затем косинус r с каждым кандидатом и покажи, что queen выигрывает. (В лекции GloVe-50d: cos(king−man+woman, queen) = 0.861.)' },
    a: { en: 'Subtract the «male» direction and add the «female» direction, then ask which real word is nearest to the result by cosine. With these toy vectors r = [1,5]; queen has cosine 0.9995 — the clear winner — while man (the subtracted word) collapses to 0.428. The analogy reduces to vector arithmetic plus a nearest-neighbour cosine search (excluding the input words). On the lecture\'s real 50-d GloVe vectors the same recipe gives queen at cos = 0.861, ahead of prince/throne ≈ 0.76.', ru: 'Вычитаем «мужское» направление и добавляем «женское», затем спрашиваем, какое реальное слово ближе всего к результату по косинусу. С этими toy-векторами r = [1,5]; у queen косинус 0.9995 — явный победитель — а man (вычтенное слово) проваливается до 0.428. Аналогия сводится к векторной арифметике плюс поиск ближайшего соседа по косинусу (исключая входные слова). На реальных 50-мерных GloVe-векторах лекции тот же рецепт даёт queen при cos = 0.861, впереди prince/throne ≈ 0.76.' },
    work: [
      'toy 2-D vectors:',
      '  king  = [4, 3]   man   = [4, 1]   woman = [1, 3]',
      '  queen = [1, 6]   throne= [3, 3]',
      '',
      'r = king − man + woman',
      '  = [4−4+1,  3−1+3] = [1, 5]',
      '',
      'cos(a,b) = (a·b)/(‖a‖‖b‖):',
      '  cos(r, queen)  = (1·1+5·6)/(√26·√37) = 31/31.01 = 0.9995  ← max',
      '  cos(r, throne) = (1·3+5·3)/(√26·√18)  = 18/21.63 = 0.832',
      '  cos(r, king)   = (4+15)/(√26·√25)     = 19/25.50 = 0.745',
      '  cos(r, man)    = (4+5)/(√26·√17)      =  9/21.02 = 0.428',
      '',
      'argmax cosine (excluding king, man, woman) = queen',
      'lecture (GloVe-50d):  cos(king−man+woman, queen) = 0.861  > prince,throne ≈ 0.76',
    ] },

  // ── DEEPENED: PCA covariance → eigen → variance explained (existing id) ──
  { id: 'l5-pca', lectures: ['05'], type: 'compute',
    q: { en: 'PCA by hand: centre the data → covariance C = (1/n)XᵀX → eigen-decompose C u = λ u → project onto top-2 eigenvectors. State variance explained = (λ₁+λ₂)/Σλ. The lecture reaches PC1 19.6% + PC2 18.1% = 37.7%.', ru: 'PCA руками: центрируй данные → ковариация C = (1/n)XᵀX → собственное разложение C u = λ u → проекция на топ-2 собственных вектора. Доля дисперсии = (λ₁+λ₂)/Σλ. В лекции PC1 19.6% + PC2 18.1% = 37.7%.' },
    a: { en: 'PCA is a causal chain: centre X (subtract the mean so the origin sits at the cloud centre); form the covariance C = (1/n)XᵀX; diagonalise — the eigenvectors uₖ of C are the principal axes and each eigenvalue λₖ is the variance along that axis; project z = Udᵀx onto the top-d eigenvectors. The fraction of variance kept by each axis is λₖ/Σⱼλⱼ. On the lecture\'s word vectors the top two axes keep only 19.6% + 18.1% = 37.7% — so a 2-D scatter discards roughly 62% of the variance, which is why low-dim plots distort.', ru: 'PCA — каузальная цепочка: центрируем X (вычитаем среднее, чтобы начало координат было в центре облака); строим ковариацию C = (1/n)XᵀX; диагонализуем — собственные векторы uₖ матрицы C это главные оси, а каждое собственное значение λₖ — дисперсия вдоль этой оси; проецируем z = Udᵀx на топ-d собственных векторов. Доля сохранённой дисперсии каждой оси = λₖ/Σⱼλⱼ. На векторах слов лекции топ-2 оси держат лишь 19.6% + 18.1% = 37.7% — 2-D scatter выбрасывает около 62% дисперсии, поэтому низкоразмерные карты искажают.' },
    work: [
      '0. centre:  X ← X − μ          (origin at the cloud centre)',
      '1. covariance:  C = (1/n) XᵀX  (symmetric, d×d)',
      '2. eigen:  C uₖ = λₖ uₖ        (uₖ = principal axes, λₖ = variance on axis k)',
      '3. project:  z = Udᵀ x         (Ud = top-d eigenvectors)',
      '4. variance kept by top-d:  (λ₁+…+λd) / Σⱼ λⱼ',
      '',
      'tiny example — eigenvalues  λ = [4.0, 3.0, 1.5, 1.0, 0.5]:',
      '  Σλ = 4.0+3.0+1.5+1.0+0.5 = 10.0',
      '  PC1 = λ₁/Σλ = 4.0/10.0 = 40.0%',
      '  PC2 = λ₂/Σλ = 3.0/10.0 = 30.0%',
      '  top-2 keep (4.0+3.0)/10.0 = 70.0%',
      '',
      'lecture (word vectors):  PC1 19.6% + PC2 18.1% = 37.7%',
      '  ⇒ a 2-D scatter discards ≈ 62.3% of the variance',
    ] },

  // ── DEEPENED: PCA vs t-SNE (existing id) ──
  { id: 'l5-pca-tsne', lectures: ['05'], type: 'concept',
    q: { en: 'PCA vs t-SNE: what does each preserve, and why can a t-SNE map mislead about global distances and cluster sizes?', ru: 'PCA vs t-SNE: что сохраняет каждый и почему t-SNE-карта может врать про глобальные расстояния и размеры кластеров?' },
    a: { en: 'PCA is a linear projection onto max-variance axes: it preserves global variance and straight-line distances, but a few axes may keep little total variance (37.7% in the lecture). t-SNE is nonlinear and optimizes a probabilistic match of LOCAL neighbourhoods, so it groups true neighbours beautifully — but cluster sizes, the gaps between clusters, and between-cluster distances on a t-SNE plot are artifacts of the perplexity and optimization, not real geometry. Read t-SNE for «who is near whom», never for «how far» or «how big».', ru: 'PCA — линейная проекция на оси максимальной дисперсии: сохраняет глобальную дисперсию и прямолинейные расстояния, но несколько осей могут держать мало дисперсии (37.7% в лекции). t-SNE нелинеен и оптимизирует вероятностное соответствие ЛОКАЛЬНЫХ соседств, поэтому красиво группирует истинных соседей — но размеры кластеров, зазоры между ними и межкластерные расстояния на t-SNE — артефакты perplexity и оптимизации, а не реальная геометрия. Читай t-SNE как «кто рядом с кем», но никогда как «насколько далеко» или «насколько большой».' } },

  // ── DEEPENED: static-embedding limit, bridge to L6 (existing id) ──
  { id: 'l5-static-limit', lectures: ['05'], type: 'concept',
    q: { en: 'Why is a static word embedding insufficient for «bank» (river vs money)? How does it connect to the implicit-PMI view of word2vec, and what does L6 fix?', ru: 'Почему статического эмбеддинга мало для «bank» (река/деньги)? Как это связано с взглядом на word2vec как неявную PMI-факторизацию и что чинит L6?' },
    a: { en: 'A static embedding stores exactly one vector per word type, learned by averaging over every context it ever appeared in — so the two senses of «bank» are collapsed into a single blurred point sitting between «river» and «money». (Levy & Goldberg showed skip-gram with negative sampling is implicitly factorizing a shifted PMI matrix, so word2vec and GloVe land in the same geometry — both still one-vector-per-word.) Contextual models (L6) recompute a token\'s vector from its actual neighbours via attention, so «river bank» and «money bank» get different vectors.', ru: 'Статический эмбеддинг хранит ровно один вектор на тип слова, выученный усреднением по всем контекстам, где оно встречалось — поэтому два смысла «bank» сливаются в одну размытую точку между «river» и «money». (Levy & Goldberg показали, что skip-gram с negative sampling неявно факторизует сдвинутую PMI-матрицу, поэтому word2vec и GloVe приходят к одной геометрии — оба всё ещё один-вектор-на-слово.) Контекстные модели (L6) пересчитывают вектор токена из его реальных соседей через attention, поэтому «river bank» и «money bank» получают разные векторы.' } },

  // ── NEW L5: CBOW vs skip-gram ──
  { id: 'l5-cbow-skipgram', lectures: ['05'], type: 'concept',
    q: { en: 'CBOW vs skip-gram: which direction does each predict, and which is better for rare words and small corpora?', ru: 'CBOW vs skip-gram: в какую сторону предсказывает каждый и какой лучше для редких слов и малых корпусов?' },
    a: { en: 'CBOW (continuous bag-of-words) predicts the CENTRE word from the (averaged) context — context → centre; it is faster and smooths over the context, which helps frequent words. Skip-gram predicts each CONTEXT word from the centre — centre → context; it generates one training pair per context word, giving rare words far more gradient signal and better representations on small corpora, at higher compute cost. Both share the same two-vectors-per-word setup and are trained with negative sampling.', ru: 'CBOW (continuous bag-of-words) предсказывает ЦЕНТРАЛЬНОЕ слово из (усреднённого) контекста — контекст → центр; он быстрее и сглаживает контекст, что помогает частым словам. Skip-gram предсказывает каждое слово КОНТЕКСТА из центра — центр → контекст; он порождает одну обучающую пару на слово контекста, давая редким словам куда больше сигнала градиента и лучшие представления на малых корпусах, ценой больших вычислений. Оба используют схему два-вектора-на-слово и обучаются negative sampling.' } },

  // ── NEW L5: GloVe objective (weighted least squares on log co-occurrence) ──
  { id: 'l5-glove', lectures: ['05'], type: 'concept',
    q: { en: 'GloVe objective: write the weighted least-squares loss on log co-occurrence and explain why it lands in the same geometry as word2vec (count vs predict).', ru: 'Объектив GloVe: запиши взвешенный МНК-лосс на логарифме совместной встречаемости и объясни, почему он приходит к той же геометрии, что и word2vec (счёт vs предсказание).' },
    a: { en: 'GloVe builds a global co-occurrence matrix X (Xᵢⱼ = how often word i appears near word j) and fits vectors so the dot product plus biases approximates the LOG count: wᵢᵀ w̃ⱼ + bᵢ + b̃ⱼ ≈ log Xᵢⱼ. The loss is a weighted least squares L = Σᵢⱼ f(Xᵢⱼ)·(wᵢᵀw̃ⱼ + bᵢ + b̃ⱼ − log Xᵢⱼ)², where the weighting f(x) caps the influence of very frequent pairs and zeroes Xᵢⱼ = 0. word2vec (predict, local windows) and GloVe (count, global matrix) end up in the same geometry because skip-gram with negative sampling implicitly factorizes a shifted-PMI matrix — predict and count are two faces of one coin.', ru: 'GloVe строит глобальную матрицу совместной встречаемости X (Xᵢⱼ = как часто слово i встречается рядом с j) и подбирает векторы так, чтобы скалярное произведение плюс смещения приближало ЛОГАРИФМ счёта: wᵢᵀ w̃ⱼ + bᵢ + b̃ⱼ ≈ log Xᵢⱼ. Лосс — взвешенный МНК L = Σᵢⱼ f(Xᵢⱼ)·(wᵢᵀw̃ⱼ + bᵢ + b̃ⱼ − log Xᵢⱼ)², где вес f(x) ограничивает влияние очень частых пар и обнуляет Xᵢⱼ = 0. word2vec (предсказание, локальные окна) и GloVe (счёт, глобальная матрица) приходят к одной геометрии, потому что skip-gram с negative sampling неявно факторизует сдвинутую PMI-матрицу — предсказание и счёт это две стороны одной монеты.' },
    work: [
      'X_ij = co-occurrence count (word i near word j, whole corpus)',
      '',
      'fit:   w_i · w̃_j + b_i + b̃_j  ≈  log X_ij',
      '',
      'weighted least-squares loss:',
      '  L = Σ_(i,j)  f(X_ij) · ( w_i·w̃_j + b_i + b̃_j − log X_ij )²',
      '',
      'weighting f(x) (caps frequent pairs, f(0)=0):',
      '  f(x) = (x / x_max)^α   if x < x_max,  else 1     (α = 3/4, x_max = 10)',
      '',
      'Levy & Goldberg (2014): skip-gram+NS implicitly factorises shifted PMI',
      '  ⇒ count (GloVe) and predict (word2vec) → same geometry',
    ] },

  // ═══════════════════════════ L6 · The Council of Attention ═══════════════════════════

  // ── DEEPENED: polysemy / contextual fix (existing id) ──
  { id: 'l6-polysemy', lectures: ['06'], type: 'concept',
    q: { en: 'Polysemy: why can\'t a static vector (L5) split the two senses of «bank», and concretely how does self-attention give «river bank» and «money bank» different vectors?', ru: 'Полисемия: почему статический вектор (L5) не разделяет смыслы «bank» и как конкретно self-attention даёт «river bank» и «money bank» разные векторы?' },
    a: { en: 'A static vector is one point per word type, identical in every sentence, so both senses of «bank» are forced into a single averaged location. Self-attention recomputes each token\'s representation as a weighted sum of the value vectors of all tokens in THIS sentence — the weights coming from query·key matches. So «bank» next to «river» attends heavily to «river» and pulls in river-ish content; «bank» next to «money» attends to «money» instead. Same input embedding for «bank», two different output vectors — meaning is now context-dependent.', ru: 'Статический вектор — одна точка на тип слова, одинаковая в любом предложении, поэтому оба смысла «bank» загнаны в одно усреднённое место. Self-attention пересчитывает представление каждого токена как взвешенную сумму value-векторов всех токенов В ЭТОМ предложении — веса берутся из совпадений query·key. Поэтому «bank» рядом с «river» сильно смотрит на «river» и втягивает «речное» содержание; «bank» рядом с «money» смотрит на «money». Один и тот же входной эмбеддинг «bank», два разных выходных вектора — смысл теперь зависит от контекста.' } },

  // ── DEEPENED: full scaled dot-product attention worked end-to-end (existing id) ──
  { id: 'l6-attention-compute', lectures: ['06'], type: 'compute',
    q: { en: 'Compute scaled dot-product attention softmax(QKᵀ/√dₖ)V on the lecture\'s toy Q,K,V (3 tokens the/cat/sat, dₖ=4). Do the full cat row: scores → /√dₖ → softmax → ·V, reaching out = [0.579, 1.996, 0.91, 0.425].', ru: 'Посчитай scaled dot-product attention softmax(QKᵀ/√dₖ)V на toy Q,K,V из лекции (3 токена the/cat/sat, dₖ=4). Полностью строку cat: scores → /√dₖ → softmax → ·V, до out = [0.579, 1.996, 0.91, 0.425].' },
    a: { en: 'For each query row: dot it with every key (QKᵀ), divide by √dₖ = √4 = 2 to keep score variance from growing with dₖ, apply a row-wise softmax to get attention weights that sum to 1, then take the weighted sum of the value rows. For cat: scores [0,4,2] → /2 = [0,2,1] → softmax [0.09, 0.665, 0.245] (cat heeds mostly itself), → output [0.579, 1.996, 0.91, 0.425] — cat\'s new, context-aware vector. The output is always a convex mixture of the value vectors.', ru: 'Для каждой строки-запроса: скалярно умножаем на каждый ключ (QKᵀ), делим на √dₖ = √4 = 2, чтобы дисперсия скоров не росла с dₖ, применяем softmax по строке для весов, сумма которых = 1, затем берём взвешенную сумму value-строк. Для cat: scores [0,4,2] → /2 = [0,2,1] → softmax [0.09, 0.665, 0.245] (cat слушает в основном себя), → output [0.579, 1.996, 0.91, 0.425] — новый контекстный вектор cat. Выход — всегда выпуклая смесь value-векторов.' },
    work: [
      'tokens the, cat, sat.   d_k = 4  ⇒  √d_k = 2',
      '  Q:  the = [1,0,1,0]   cat = [0,2,0,1]   sat = [1,1,0,0]',
      '  K:  the = [1,0,1,0]   cat = [0,1,0,2]   sat = [2,1,0,0]',
      '  V:  the = [1,0,0,2]   cat = [0,3,1,0]   sat = [2,0,1,1]',
      '',
      'cat query  Q_cat = [0,2,0,1]',
      'scores = Q_cat · Kᵀ  (dot with each key row):',
      '  · K_the = 0·1+2·0+0·1+1·0 = 0',
      '  · K_cat = 0·0+2·1+0·0+1·2 = 4',
      '  · K_sat = 0·2+2·1+0·0+1·0 = 2',
      '  scores = [0, 4, 2]',
      '',
      'scale /√d_k:  [0,4,2]/2 = [0, 2, 1]',
      '',
      'softmax([0,2,1]):',
      '  exp = [e^0, e^2, e^1] = [1.000, 7.389, 2.718],  Σ = 11.107',
      '  weights = [0.090, 0.665, 0.245]   (Σ = 1, cat mostly heeds itself)',
      '',
      'output = weights · V  (weighted sum of value rows):',
      '  dim0: 0.090·1 + 0.665·0 + 0.245·2 = 0.579',
      '  dim1: 0.090·0 + 0.665·3 + 0.245·0 = 1.996',
      '  dim2: 0.090·0 + 0.665·1 + 0.245·1 = 0.910',
      '  dim3: 0.090·2 + 0.665·0 + 0.245·1 = 0.425',
      '  out_cat = [0.579, 1.996, 0.910, 0.425]',
    ] },

  // ── DEEPENED: √dₖ scaling (existing id) ──
  { id: 'l6-sqrt-dk', lectures: ['06'], type: 'compute',
    q: { en: 'Why divide by √dₖ in attention? Give the variance argument and show numerically what happens to softmax([0,4,2]) vs softmax([0,2,1]).', ru: 'Почему делим на √dₖ в attention? Дай аргумент про дисперсию и покажи численно, что происходит с softmax([0,4,2]) против softmax([0,2,1]).' },
    a: { en: 'If query and key entries are independent with unit variance, the dot product qᵀk = Σ qᵢkᵢ has variance dₖ, so scores grow like √dₖ in scale. Large scores push softmax toward a near one-hot distribution where almost all gradient vanishes (the saturated regime), so training stalls. Dividing by √dₖ rescales the score variance back to ≈1 regardless of dₖ. Numerically the unscaled scores [0,4,2] give a peaky [0.016, 0.867, 0.117] while the scaled [0,2,1] give the gentler, trainable [0.09, 0.665, 0.245].', ru: 'Если элементы запроса и ключа независимы с единичной дисперсией, скалярное произведение qᵀk = Σ qᵢkᵢ имеет дисперсию dₖ, поэтому масштаб скоров растёт как √dₖ. Большие скоры загоняют softmax в почти one-hot распределение, где почти весь градиент исчезает (режим насыщения), и обучение встаёт. Деление на √dₖ возвращает дисперсию скоров к ≈1 независимо от dₖ. Численно немасштабированные скоры [0,4,2] дают острое [0.016, 0.867, 0.117], а масштабированные [0,2,1] — более мягкое, обучаемое [0.09, 0.665, 0.245].' },
    work: [
      'q, k entries iid, mean 0, var 1:',
      '  qᵀk = Σ_(i=1)^(d_k) qᵢ kᵢ  ⇒  Var(qᵀk) = d_k     (scale ∝ √d_k)',
      '  scale by 1/√d_k  ⇒  Var = 1   (stable, independent of d_k)',
      '',
      'unscaled  softmax([0,4,2]):',
      '  exp = [1, 54.60, 7.389], Σ = 62.99',
      '  = [0.016, 0.867, 0.117]      ← peaky, near one-hot, tiny gradient',
      '',
      'scaled /√4=2  softmax([0,2,1]):',
      '  exp = [1, 7.389, 2.718], Σ = 11.107',
      '  = [0.090, 0.665, 0.245]      ← gentler, gradient flows',
    ] },

  // ── DEEPENED: Transformer block (existing id) ──
  { id: 'l6-block', lectures: ['06'], type: 'concept',
    q: { en: 'Assemble the Transformer encoder block (multi-head attention → Add&Norm → FFN → Add&Norm). Why residuals, why LayerNorm, and what does the position-wise FFN add?', ru: 'Собери блок энкодера Transformer (multi-head attention → Add&Norm → FFN → Add&Norm). Зачем residuals, зачем LayerNorm и что добавляет позиционная FFN?' },
    a: { en: 'A block is: x → MHA(x), add the residual x and LayerNorm; then → FFN, add the residual and LayerNorm again. Residual connections give the gradient an identity short-cut so very deep stacks still train (no vanishing). LayerNorm normalizes each token vector to mean 0 / variance 1 (then scale+shift), keeping activations at a stable scale across depth. Attention only MIXES tokens linearly (a weighted average of values) — the position-wise FFN (a 2-layer MLP applied to each token independently, usually d → 4d → d with a nonlinearity) adds the per-token nonlinear transformation that lets the model actually compute, not just average.', ru: 'Блок: x → MHA(x), прибавить residual x и LayerNorm; затем → FFN, снова прибавить residual и LayerNorm. Residual-связи дают градиенту identity-обходной путь, чтобы очень глубокие стопки обучались (нет затухания). LayerNorm нормирует каждый вектор токена к среднему 0 / дисперсии 1 (затем масштаб+сдвиг), удерживая активации на стабильном масштабе по глубине. Attention лишь линейно ПЕРЕМЕШИВАЕТ токены (взвешенное среднее value) — позиционная FFN (2-слойный MLP на каждый токен отдельно, обычно d → 4d → d с нелинейностью) добавляет нелинейное преобразование на токен, позволяющее модели реально вычислять, а не только усреднять.' } },

  // ── DEEPENED: InfoNCE objective formulated + worked with lecture numbers (existing id) ──
  { id: 'l6-infonce', lectures: ['06'], type: 'compute',
    q: { en: 'Write the InfoNCE / NT-Xent objective mathematically (softmax over cosine similarities / temperature τ) and compute it on the lecture\'s numbers: anchor cat, positive kitten cos=0.639, negatives airplane 0.365, computer 0.353, france 0.091, τ=0.1 → loss ≈ 0.119.', ru: 'Запиши InfoNCE / NT-Xent объектив математически (softmax по косинусным сходствам / температура τ) и посчитай на числах лекции: якорь cat, позитив kitten cos=0.639, негативы airplane 0.365, computer 0.353, france 0.091, τ=0.1 → loss ≈ 0.119.' },
    a: { en: 'InfoNCE turns «beat the negatives» into a softmax classification: which candidate is the true positive? p⁺ = exp(sim⁺/τ) / [exp(sim⁺/τ) + Σ exp(sim⁻/τ)] over cosine similarities divided by temperature τ, and the loss is −log p⁺. Low τ sharpens the distribution (hard negatives matter more); minimizing −log p⁺ drives p⁺ → 1, pulling the positive in and pushing negatives out. With the lecture\'s cosines and τ=0.1: dividing by τ multiplies every cosine by 10, so the positive (6.39) dominates the negatives (3.65, 3.53, 0.91); p⁺ ≈ 0.888 and L = −log 0.888 ≈ 0.119. In a batch, every example\'s own positive is on the diagonal of the cosine matrix and the off-diagonal entries are in-batch negatives — free, no extra labels.', ru: 'InfoNCE превращает «победи негативы» в softmax-классификацию: какой кандидат — истинный позитив? p⁺ = exp(sim⁺/τ) / [exp(sim⁺/τ) + Σ exp(sim⁻/τ)] по косинусным сходствам, делённым на температуру τ, а лосс — это −log p⁺. Низкая τ заостряет распределение (hard negatives важнее); минимизация −log p⁺ гонит p⁺ → 1, притягивая позитив и отталкивая негативы. С косинусами лекции и τ=0.1: деление на τ умножает каждый косинус на 10, поэтому позитив (6.39) доминирует над негативами (3.65, 3.53, 0.91); p⁺ ≈ 0.888 и L = −log 0.888 ≈ 0.119. В батче собственный позитив каждого примера — на диагонали косинусной матрицы, а внедиагональные элементы — in-batch негативы — бесплатны, без лишней разметки.' },
    work: [
      'cosines to anchor cat:  positive kitten = 0.639',
      '  negatives: airplane 0.365, computer 0.353, france 0.091      τ = 0.1',
      '',
      'objective:           exp(sim⁺/τ)',
      '  p⁺ = ────────────────────────────────────────────',
      '       exp(sim⁺/τ) + Σ_(x⁻) exp(sim⁻/τ)',
      '  L_InfoNCE = − log p⁺',
      '',
      'logits = sim/τ  (×10):  pos 6.39 ; negs 3.65, 3.53, 0.91',
      'exponentials:',
      '  exp(6.39) = 595.86',
      '  exp(3.65) =  38.47',
      '  exp(3.53) =  34.12',
      '  exp(0.91) =   2.48',
      '',
      'denominator = 595.86 + 38.47 + 34.12 + 2.48 = 670.94',
      'p⁺ = 595.86 / 670.94 = 0.888',
      'L  = − log(0.888) = 0.119      (lecture value ≈ 0.1191)',
      '',
      'in-batch: cosine matrix B×B → positives on the diagonal,',
      '          off-diagonal = free negatives (no extra labels)',
    ] },

  // ── DEEPENED: anisotropy (existing id) ──
  { id: 'l6-anisotropy', lectures: ['06', '02'], type: 'concept',
    q: { en: 'What is anisotropy (callback L2), why does it make raw transformer cosines untrustworthy, and how do contrastive training / whitening fix it?', ru: 'Что такое anisotropy (callback L2), почему она делает сырые косинусы трансформера ненадёжными и как её чинит контрастное обучение / whitening?' },
    a: { en: 'Anisotropy is the tendency of raw transformer token/sentence embeddings to crowd into a narrow cone rather than spread over the sphere, so ALL pairwise cosines are high (e.g. 0.6–0.9) and barely distinguish related from unrelated — the same distance-concentration failure flagged in L2. Contrastive training fixes it directly: by pushing negatives apart it spreads the embeddings to fill the space (the «uniformity» term), restoring contrast. Post-hoc whitening is a cheaper fix: linearly transform the vectors to zero mean and identity covariance so the cone is re-centred and isotropized.', ru: 'Anisotropy — склонность сырых эмбеддингов токенов/предложений трансформера жаться в узкий конус, а не разлетаться по сфере, поэтому ВСЕ попарные косинусы высокие (напр. 0.6–0.9) и почти не различают связанное от несвязанного — тот же провал концентрации расстояний из L2. Контрастное обучение чинит это напрямую: отталкивая негативы, оно раздвигает эмбеддинги, заполняя пространство (член «uniformity»), и восстанавливает контраст. Whitening постфактум — более дешёвый способ: линейно преобразовать векторы к нулевому среднему и единичной ковариации, чтобы конус был перецентрирован и изотропизован.' } },

  // ── NEW L6: Q,K,V as learned projections + multi-head split ──
  { id: 'l6-qkv-multihead', lectures: ['06'], type: 'concept',
    q: { en: 'Where do Q, K, V come from, and how does multi-head attention split a model of dimension d into h heads of d/h? Give the shapes.', ru: 'Откуда берутся Q, K, V и как multi-head attention делит модель размерности d на h голов по d/h? Укажи размерности.' },
    a: { en: 'Q, K, V are not raw inputs — they are linear projections of the same token matrix X ∈ ℝ^(T×d): Q = XW_Q, K = XW_K, V = XW_V, where W_Q, W_K, W_V are the only learned parameters of self-attention (the softmax-and-weighted-sum machine itself is weight-free). Multi-head attention runs h independent heads, each projecting into a d/h-dimensional subspace with its own W_Q^(i), W_K^(i), W_V^(i); each head computes attention separately, the h outputs (each d/h wide) are concatenated back to width d and passed through an output projection W_O. Different subspaces let heads specialize — one tracks syntax, another coreference. Example: d=512, h=8 → each head is 512/8 = 64-dimensional.', ru: 'Q, K, V — не сырые входы, а линейные проекции одной матрицы токенов X ∈ ℝ^(T×d): Q = XW_Q, K = XW_K, V = XW_V, где W_Q, W_K, W_V — единственные обучаемые параметры self-attention (сам механизм softmax-и-взвешенной-суммы без весов). Multi-head attention запускает h независимых голов, каждая проецирует в подпространство размерности d/h со своими W_Q^(i), W_K^(i), W_V^(i); каждая голова считает attention отдельно, h выходов (каждый шириной d/h) конкатенируются обратно до ширины d и проходят выходную проекцию W_O. Разные подпространства позволяют головам специализироваться — одна следит за синтаксисом, другая за кореференцией. Пример: d=512, h=8 → каждая голова 512/8 = 64-мерная.' },
    work: [
      'input  X ∈ ℝ^(T×d)   (T tokens, model dim d)',
      '',
      'single head — learned projections:',
      '  Q = X W_Q,  K = X W_K,  V = X W_V      (W_* are the ONLY params)',
      '',
      'multi-head (h heads, each d/h wide):',
      '  head_i = Attention(X W_Q^(i), X W_K^(i), X W_V^(i)),   i=1..h',
      '  W_*^(i) : d × (d/h)        head_i : T × (d/h)',
      '  MHA(X) = Concat(head_1, …, head_h) W_O',
      '           Concat : T × d        W_O : d × d',
      '',
      'example: d = 512, h = 8  ⇒  d/h = 64 per head',
    ] },

  // ── NEW L6: sinusoidal positional encoding ──
  { id: 'l6-positional', lectures: ['06'], type: 'compute',
    q: { en: 'Sinusoidal positional encoding: write PE(pos,2i)=sin(pos/10000^(2i/d)), PE(pos,2i+1)=cos(...), say why it is needed and why this form. Compute the d=4 vector for pos=0 and pos=1.', ru: 'Синусоидальное позиционное кодирование: запиши PE(pos,2i)=sin(pos/10000^(2i/d)), PE(pos,2i+1)=cos(...), объясни зачем оно нужно и почему такая форма. Посчитай вектор для d=4 при pos=0 и pos=1.' },
    a: { en: 'Self-attention is permutation-invariant — it treats the input as a SET, so it has no idea of word order. Positional encoding injects order by adding a position-dependent vector to each token embedding (X′ = X + PE). Each dimension is a sinusoid of its own wavelength: low dimensions oscillate fast (fine local order), high dimensions slowly (coarse global position), so every position gets a unique fingerprint. Because sin/cos of a shifted angle are linear combinations of the unshifted ones, relative offsets become linear functions — the model can generalize to relative positions. For d=4: pos=0 → [0,1,0,1]; pos=1 → [sin 1, cos 1, sin 0.01, cos 0.01] ≈ [0.841, 0.540, 0.010, 1.000].', ru: 'Self-attention перестановочно-инвариантен — он трактует вход как МНОЖЕСТВО, поэтому не знает о порядке слов. Позиционное кодирование вносит порядок, прибавляя зависящий от позиции вектор к каждому эмбеддингу токена (X′ = X + PE). Каждое измерение — синусоида своей длины волны: низкие измерения колеблются быстро (тонкий локальный порядок), высокие — медленно (грубая глобальная позиция), поэтому каждая позиция получает уникальный отпечаток. Поскольку sin/cos сдвинутого угла — линейные комбинации несдвинутых, относительные сдвиги становятся линейными функциями — модель обобщает на относительные позиции. Для d=4: pos=0 → [0,1,0,1]; pos=1 → [sin 1, cos 1, sin 0.01, cos 0.01] ≈ [0.841, 0.540, 0.010, 1.000].' },
    work: [
      'PE(pos, 2i)   = sin( pos / 10000^(2i/d) )',
      'PE(pos, 2i+1) = cos( pos / 10000^(2i/d) )',
      'added to the token:   X′ = X + PE',
      '',
      'd = 4 → pairs i=0 (dims 0,1) and i=1 (dims 2,3):',
      '  i=0:  divisor 10000^(0)     = 1      (fast: wavelength 2π ≈ 6.28)',
      '  i=1:  divisor 10000^(2/4)   = 100    (slow: wavelength 2π·100 ≈ 628)',
      '',
      'pos = 0:',
      '  [sin0, cos0, sin0, cos0] = [0, 1, 0, 1]',
      '',
      'pos = 1:',
      '  dim0 sin(1/1)   = sin(1)    = 0.841',
      '  dim1 cos(1/1)   = cos(1)    = 0.540',
      '  dim2 sin(1/100) = sin(0.01) = 0.010',
      '  dim3 cos(1/100) = cos(0.01) = 1.000',
      '  PE(1) ≈ [0.841, 0.540, 0.010, 1.000]',
      '',
      'low dims move fast (local order) · high dims slow (global position)',
    ] },

  // ── NEW L6: triplet / margin loss ──
  { id: 'l6-triplet', lectures: ['06'], type: 'compute',
    q: { en: 'Triplet / margin loss: write L = max(0, m + d(a,p) − d(a,n)) for anchor a, positive p, negative n, and compute it for two cases (an «easy» triplet and a margin-violating one). How does InfoNCE generalize it?', ru: 'Triplet / margin loss: запиши L = max(0, m + d(a,p) − d(a,n)) для якоря a, позитива p, негатива n, и посчитай для двух случаев («лёгкий» триплет и нарушающий margin). Как InfoNCE его обобщает?' },
    a: { en: 'Triplet loss is a hinge that wants the anchor closer to its positive than to its negative by at least a margin m: L = max(0, m + d(a,p) − d(a,n)). If the negative is already farther than the positive by more than m, the bracket is negative and the loss is 0 — the triplet is «easy» and contributes nothing. If the margin is violated, the loss is positive and gradients pull p in / push n out. InfoNCE generalizes it from ONE negative to MANY simultaneously: instead of a single pairwise margin it scores the positive against the whole batch in a softmax over similarities — a far stronger signal, which is why dense retrievers use in-batch InfoNCE rather than raw triplets.', ru: 'Triplet loss — это hinge, который хочет, чтобы якорь был ближе к позитиву, чем к негативу, минимум на margin m: L = max(0, m + d(a,p) − d(a,n)). Если негатив уже дальше позитива более чем на m, скобка отрицательна и лосс = 0 — триплет «лёгкий» и ничего не даёт. Если margin нарушен, лосс положителен и градиенты притягивают p / отталкивают n. InfoNCE обобщает его с ОДНОГО негатива на МНОГО сразу: вместо одного парного margin он оценивает позитив против всего батча в softmax по сходствам — куда более сильный сигнал, поэтому плотные ретриверы используют in-batch InfoNCE, а не сырые триплеты.' },
    work: [
      'L = max(0,  m + d(a,p) − d(a,n) )      margin m = 0.2  (d = distance)',
      '',
      'case A — easy triplet (positive much closer):',
      '  d(a,p) = 0.3,  d(a,n) = 0.9',
      '  bracket = 0.2 + 0.3 − 0.9 = −0.4',
      '  L = max(0, −0.4) = 0          ← satisfied, no gradient',
      '',
      'case B — margin violated (negative too close):',
      '  d(a,p) = 0.5,  d(a,n) = 0.6',
      '  bracket = 0.2 + 0.5 − 0.6 = 0.1',
      '  L = max(0, 0.1) = 0.1         ← pull p in, push n out',
      '',
      'InfoNCE = triplet generalised: 1 negative → softmax over MANY at once',
    ] },

  // ── NEW L6: masked-language-model objective ──
  { id: 'l6-mlm', lectures: ['06'], type: 'concept',
    q: { en: 'Masked-language-model (MLM) objective: how is BERT pre-trained, what fraction is masked, and why is bidirectional MLM better for retrieval encoders than left-to-right language modelling?', ru: 'Masked-language-model (MLM) объектив: как претренируется BERT, какую долю маскируют и почему двунаправленный MLM лучше для энкодеров поиска, чем left-to-right языковое моделирование?' },
    a: { en: 'MLM randomly replaces ~15% of input tokens with a [MASK] token (the 80/10/10 recipe: 80% [MASK], 10% random, 10% unchanged) and trains the model to predict the original token from BOTH-sided context, minimizing cross-entropy over the vocabulary at the masked positions: L = −Σ_(i∈masked) log P(xᵢ | x_context). Because attention sees the whole sentence at once, each token\'s representation fuses left and right context — exactly what an encoder/bi-encoder for retrieval needs (it pools a full-sentence vector, not a next-token predictor). Left-to-right (causal) LMs only see the past, so they are weaker as fixed-text encoders, though stronger for generation. Note MLM is only the pre-training starting point for a retrieval encoder — raw MLM vectors still need contrastive fine-tuning (L6 contrastive) before cosine nearness means relevance.', ru: 'MLM случайно заменяет ~15% входных токенов на токен [MASK] (рецепт 80/10/10: 80% [MASK], 10% случайный, 10% без изменений) и обучает модель предсказывать исходный токен из ОБЕИХ сторон контекста, минимизируя кросс-энтропию по словарю в маскированных позициях: L = −Σ_(i∈masked) log P(xᵢ | x_context). Поскольку attention видит всё предложение сразу, представление каждого токена сплавляет левый и правый контекст — именно это нужно энкодеру/bi-encoder для поиска (он пулит вектор всего предложения, а не предиктор следующего токена). Left-to-right (каузальные) LM видят только прошлое, поэтому слабее как энкодеры фиксированного текста, хотя сильнее для генерации. MLM — лишь стартовая точка претрейна энкодера поиска: сырые MLM-векторы всё ещё требуют контрастного дообучения (L6 contrastive), прежде чем косинусная близость станет означать релевантность.' } },

// ───────────────────────── L7 · Scouts and Judges ─────────────────────────
  { id: 'l7-bi-vs-cross', lectures: ['07'], type: 'concept',
    q: { en: 'Bi-encoder vs cross-encoder: independent vs joint encoding — which can precompute doc vectors, and why does that decide scalability?', ru: 'Bi- vs cross-encoder: независимое vs совместное кодирование — кто может предпосчитать вектора документов и почему это решает масштабируемость?' },
    a: { en: 'A bi-encoder encodes query and doc through two (often shared) towers separately, so doc vectors are query-independent: precompute all of them offline into an ANN index and, at query time, encode q once and do cheap dot-products. A cross-encoder concatenates [CLS] q [SEP] d [SEP] and runs full cross-attention over the pair, so the score is a property of the pair — nothing can be cached and you would need one transformer pass per document, i.e. O(N) per query. That single fact (cache the doc side or not) is why the bi-encoder retrieves a galaxy of docs while the cross-encoder is confined to reranking a short list.', ru: 'Bi-encoder кодирует запрос и документ двумя (часто общими) башнями порознь, поэтому вектора документов не зависят от запроса: предпосчитываем их офлайн в ANN-индекс, а на запросе кодируем q один раз и считаем дешёвые dot-product’ы. Cross-encoder склеивает [CLS] q [SEP] d [SEP] и гоняет полное cross-attention по паре, так что оценка — свойство пары: кэшировать нечего, нужен прогон трансформера на каждый документ, то есть O(N) на запрос. Именно это (можно ли закэшировать сторону документа) и решает: bi-encoder достаёт «галактику» документов, а cross-encoder годится лишь на реранк короткого списка.' } },

  { id: 'l7-biencoder-compute', lectures: ['07'], type: 'compute',
    q: { en: 'Score a (query, doc) pair with a bi-encoder by hand: take the toy 4-axis vectors, compute the dot product and the cosine, and say why the cosine, not the dot, is the fair comparison.', ru: 'Оцени пару (запрос, документ) bi-encoder’ом руками: возьми toy-вектора по 4 осям, посчитай dot-product и cosine, и объясни, почему честно сравнивать косинусом, а не dot.' },
    a: { en: 'Both q and d are embedded into one shared space, so the dot product q·d is already a relevance signal: it is 2 for the relevant doc and 0 for the off-topic one. Dividing by the norms gives the cosine 2/√6 ≈ 0.8165 for the relevant pair and 0 for the irrelevant — length-invariant, so a longer document is not rewarded merely for having more nonzero axes. The real 384-dim SBERT (all-MiniLM-L6-v2) agrees in direction (0.6838 > 0.4082): toy arithmetic and the real encoder point the same way.', ru: 'И q, и d вложены в одно общее пространство, поэтому dot-product q·d — уже сигнал релевантности: 2 для релевантного документа и 0 для постороннего. Деление на нормы даёт косинус 2/√6 ≈ 0.8165 для релевантной пары и 0 для нерелевантной — он инвариантен к длине, так что длинный документ не награждается лишь за большее число ненулевых осей. Реальный 384-мерный SBERT (all-MiniLM-L6-v2) согласен по направлению (0.6838 > 0.4082): игрушечная арифметика и настоящий энкодер указывают туда же.' },
    work: [
      'axes = (finance, geography, animal, water)',
      'q       = [0, 1, 0, 1]    "river bank"',
      'd_rel   = [0, 1, 1, 1]    "a beaver by the river bank"',
      'd_irr   = [1, 0, 0, 0]    "the bank approved my loan"',
      '',
      'q . d_rel = 0*0 + 1*1 + 0*1 + 1*1 = 2',
      'q . d_irr = 0*1 + 1*0 + 0*0 + 1*0 = 0',
      '',
      '|q|     = sqrt(0+1+0+1) = sqrt(2)',
      '|d_rel| = sqrt(0+1+1+1) = sqrt(3)',
      'cos(q,d_rel) = 2 / (sqrt2 * sqrt3) = 2/sqrt6 = 0.8165',
      'cos(q,d_irr) = 0 / (sqrt2 * 1)     = 0',
      '',
      'real SBERT (all-MiniLM-L6-v2): cos_rel 0.6838 > cos_irr 0.4082' ] },

  { id: 'l7-cross-firststage', lectures: ['07'], type: 'concept',
    q: { en: 'Why is a cross-encoder more accurate but unusable as a first-stage retriever? Walk the [CLS] → logit → score head as in the toy example.', ru: 'Почему cross-encoder точнее, но не годится как первый этап? Проследи голову [CLS] → логит → оценка на toy-примере.' },
    a: { en: 'Joint input [CLS] q [SEP] d [SEP] lets every query token attend to every doc token, so the model can catch interactions a Scout misses — e.g. a negation or a word collision — which is what makes it accurate. A small linear head reads the [CLS] vector: logit = w·[CLS] + b, score = σ(logit). With w=[0.5,1.0], b=0.4, a relevant [CLS]=[1.0,1.5] gives logit 2.4 → σ=0.9168, while a constructed negative [1.0,−2.0] gives −1.1 → σ=0.2497. But because the score lives on the pair, you cannot precompute or cache anything, so scoring the whole corpus is O(N) transformer passes — fine for reranking k≈100, impossible as a retriever over millions.', ru: 'Совместный вход [CLS] q [SEP] d [SEP] даёт каждому токену запроса смотреть на каждый токен документа, поэтому модель ловит взаимодействия, которые Разведчик упускает — напр. отрицание или коллизию слов, — отсюда и точность. Маленькая линейная голова читает вектор [CLS]: logit = w·[CLS] + b, score = σ(logit). При w=[0.5,1.0], b=0.4 релевантный [CLS]=[1.0,1.5] даёт logit 2.4 → σ=0.9168, а сконструированный негатив [1.0,−2.0] даёт −1.1 → σ=0.2497. Но раз оценка — свойство пары, ничего нельзя предпосчитать или закэшировать, и скоринг всего корпуса — это O(N) прогонов трансформера: годится для реранка k≈100, но не как ретривер по миллионам.' },
    work: [
      'head:  w = [0.5, 1.0],  b = 0.4',
      'logit = w . [CLS] + b,   score = sigma(logit)',
      '',
      'relevant  [CLS] = [1.0, 1.5]',
      '  logit = 0.5*1.0 + 1.0*1.5 + 0.4 = 2.4',
      '  score = sigma(2.4)  = 0.9168',
      '',
      'negation  [CLS] = [1.0, -2.0]',
      '  logit = 0.5*1.0 + 1.0*(-2.0) + 0.4 = -1.1',
      '  score = sigma(-1.1) = 0.2497',
      '',
      'cost per query corpus-wide = N transformer passes  ->  O(N)' ] },

  { id: 'l7-dpr-objective', lectures: ['07', '06'], type: 'compute',
    q: { en: 'Formulate the DPR / bi-encoder contrastive training objective with in-batch negatives, and work a tiny N=2 batch through it. What plays the role of the positive, and why is a bigger batch better?', ru: 'Сформулируй контрастную цель обучения DPR / bi-encoder с in-batch негативами и прогони мини-батч N=2. Что играет роль позитива и почему больший батч лучше?' },
    a: { en: 'A batch of N matched (query, positive-doc) pairs is scored into an N×N similarity matrix S = Q·Dᵀ. The InfoNCE loss is a row-wise softmax cross-entropy with the diagonal as the positive: L = −(1/N) Σᵢ log[ exp(S_ii/τ) / Σⱼ exp(S_ij/τ) ]. Row i pulls query i toward its own document (S_ii) and pushes it away from every other document in the batch — the off-diagonal entries are in-batch negatives that cost no extra forward pass, so a bigger batch simply hands the loss more (and harder) negatives for free. This is exactly DPR’s negative log-likelihood of the positive and the same InfoNCE as L6; temperature τ sharpens the softmax (smaller τ leans harder on the closest negatives).', ru: 'Батч из N сопоставленных пар (запрос, позитив-документ) скорится в матрицу сходств N×N: S = Q·Dᵀ. Лосс InfoNCE — построчная softmax-кросс-энтропия с диагональю как позитивом: L = −(1/N) Σᵢ log[ exp(S_ii/τ) / Σⱼ exp(S_ij/τ) ]. Строка i тянет запрос i к своему документу (S_ii) и отталкивает от всех остальных документов батча — внедиагональные элементы это in-batch негативы, не требующие лишнего прогона, поэтому больший батч просто бесплатно даёт лоссу больше (и более трудных) негативов. Это в точности отрицательное лог-правдоподобие позитива у DPR и та же InfoNCE, что в L6; температура τ заостряет softmax (меньше τ — сильнее давит на ближайшие негативы).' },
    work: [
      'batch of N pairs -> S = Q . D^T  (N x N),  positive = diagonal S_ii',
      'L = -(1/N) * SUM_i  log[ exp(S_ii/tau) / SUM_j exp(S_ij/tau) ]',
      '',
      'toy:  N = 2,  tau = 0.2',
      '        d1     d2',
      '  q1 [ 0.8    0.2 ]   <- diag 0.8 is the positive',
      '  q2 [ 0.3    0.7 ]   <- diag 0.7 is the positive',
      '',
      'row1:  exp(0.8/0.2)=54.60,  exp(0.2/0.2)=2.72',
      '  P_11 = 54.60/(54.60+2.72) = 0.9526   -log = 0.0486',
      'row2:  exp(0.3/0.2)=4.48,   exp(0.7/0.2)=33.12',
      '  P_22 = 33.12/(4.48+33.12) = 0.8808   -log = 0.1269',
      '',
      'L = (0.0486 + 0.1269)/2 = 0.0878',
      'off-diagonal cells = in-batch negatives (free) -> bigger N, more negatives' ] },

  { id: 'l7-distillation', lectures: ['07'], type: 'concept',
    q: { en: 'Distillation from a cross-encoder teacher: write the Margin-MSE objective and say why matching the teacher’s margin (and the KL listwise variant) beats training on binary labels.', ru: 'Дистилляция из cross-encoder-учителя: запиши цель Margin-MSE и объясни, почему подгонка отрыва учителя (и listwise-вариант с KL) лучше обучения на бинарных метках.' },
    a: { en: 'A strong but slow cross-encoder teacher T scores pairs; the fast bi-encoder student S learns to imitate it. Margin-MSE matches the margin rather than the raw score: L = MSE( (s_S(q,d⁺) − s_S(q,d⁻)), (s_T(q,d⁺) − s_T(q,d⁻)) ). Using the gap, not the absolute value, makes it robust to the two architectures living on different score scales. Soft teacher scores carry graded relevance information that a 0/1 label throws away, so the student learns finer distinctions and denoised supervision; the listwise variant replaces the pairwise margin with a KL divergence over the teacher’s full score distribution on a candidate list. This is the recipe inside TAS-B, ColBERTv2, RocketQAv2 and E5.', ru: 'Сильный, но медленный cross-encoder-учитель T оценивает пары; быстрый bi-encoder-ученик S учится его имитировать. Margin-MSE подгоняет именно отрыв, а не сырой балл: L = MSE( (s_S(q,d⁺) − s_S(q,d⁻)), (s_T(q,d⁺) − s_T(q,d⁻)) ). Использование разницы, а не абсолюта, делает метод устойчивым к тому, что две архитектуры живут в разных шкалах оценок. Мягкие оценки учителя несут градуированную релевантность, которую метка 0/1 выбрасывает, поэтому ученик ловит более тонкие различия и обесшумленный надзор; listwise-вариант заменяет парный отрыв на KL-дивергенцию по всему распределению оценок учителя на списке кандидатов. Так учат TAS-B, ColBERTv2, RocketQAv2 и E5.' } },

  { id: 'l7-cls-vs-mean', lectures: ['07'], type: 'concept',
    q: { en: '[CLS]-pooling vs mean-pooling for a bi-encoder’s sentence vector: what does each do, and why is mean-pooling (SBERT) usually the safer default?', ru: '[CLS]-пулинг vs mean-пулинг для предложенческого вектора bi-encoder: что делает каждый и почему mean-пулинг (SBERT) обычно безопаснее по умолчанию?' },
    a: { en: 'Both turn a sequence of token vectors into one fixed vector. [CLS]-pooling takes the single hidden state of the prepended [CLS] token; mean-pooling averages all token vectors (usually masking out padding). [CLS] is only meaningful if the model was trained so that token aggregates a sentence summary — out of the box a raw BERT [CLS] is a poor sentence embedding. Mean-pooling spreads the signal over every token, is less sensitive to a single position, and is the SBERT default that tends to give stronger sentence vectors without special pretraining. Either way the choice must match training: you pool the same way at index time and query time.', ru: 'Оба превращают последовательность токен-векторов в один фиксированный вектор. [CLS]-пулинг берёт единственное скрытое состояние добавленного спереди токена [CLS]; mean-пулинг усредняет все токен-вектора (обычно маскируя паддинг). [CLS] осмыслен, только если модель так обучали, что этот токен агрегирует сводку предложения — «из коробки» сырой [CLS] у BERT плохой sentence-эмбеддинг. Mean-пулинг распределяет сигнал по всем токенам, менее чувствителен к одной позиции и по умолчанию используется в SBERT, давая более сильные предложенческие вектора без спецпретрейна. В любом случае выбор должен совпадать с обучением: пулишь одинаково и при индексации, и на запросе.' } },

  { id: 'l7-recall-ceiling', lectures: ['07'], type: 'concept',
    q: { en: 'In a cascade (retrieve top-k → rerank), why is the pipeline’s quality capped by the retriever’s recall@k?', ru: 'В каскаде (retrieve top-k → rerank) почему качество ограничено recall@k ретривера?' },
    a: { en: 'The reranker only reorders the candidate set it is handed; it can never add a document the first stage failed to retrieve. So any relevant doc outside the top-k is permanently lost, and the best possible final ranking is bounded by which relevant docs are present — i.e. by recall@k. This is why you tune the retriever for recall and the reranker for precision-at-the-top, and why a recall-aware evaluation is needed to even see the ceiling.', ru: 'Реранкер лишь переставляет выданный ему набор кандидатов; он никогда не добавит документ, который первый этап не извлёк. Поэтому любой релевантный документ вне top-k потерян безвозвратно, и лучшее возможное итоговое ранжирование ограничено тем, какие релевантные документы присутствуют — то есть recall@k. Отсюда: ретривер настраивают на recall, а реранкер — на точность наверху; и чтобы вообще увидеть потолок, нужна метрика, чувствительная к recall.' } },

  { id: 'l7-rerank-depth', lectures: ['07'], type: 'concept',
    q: { en: 'Rerank depth k vs latency: what is the tradeoff, and when does going deeper stop helping?', ru: 'Глубина реранка k против задержки: компромисс и где углубление перестаёт помогать?' },
    a: { en: 'Cross-encoder reranking costs one model pass per candidate, so latency grows linearly in k. Quality rises with k only while the deeper slots still contain relevant docs the retriever placed below the current cutoff; once you have captured essentially all of the retriever’s recall, deeper reranking reorders only non-relevant tail and buys latency, not nDCG. The sweet spot is the smallest k that already holds the retriever’s recall — typically k of order tens to a few hundred.', ru: 'Реранк cross-encoder’ом стоит один прогон модели на кандидата, поэтому задержка растёт линейно по k. Качество растёт с k лишь пока в более глубоких слотах ещё есть релевантные документы, которые ретривер поставил ниже текущего порога; как только собран практически весь recall ретривера, более глубокий реранк переставляет лишь нерелевантный хвост и покупает задержку, а не nDCG. Оптимум — наименьшее k, уже удерживающее recall ретривера: обычно от десятков до пары сотен.' } },

  { id: 'l7-dense-not-free', lectures: ['07'], type: 'concept',
    q: { en: 'Refute “dense always beats BM25” using the zero-shot BEIR evidence.', ru: 'Опровергни «dense всегда бьёт BM25» данными zero-shot BEIR.' },
    a: { en: 'On out-of-domain BEIR, BM25 is a robust baseline that beats a vanilla dense retriever (e.g. BM25 ≈ 0.43 vs DPR ≈ 0.38 nDCG@10 averaged across tasks). Dense retrievers win in-domain, where their training distribution matches the queries, but degrade out-of-domain because the learned semantic space does not transfer; BM25’s exact-term matching has no such domain dependence. This is the motivation for hybrid retrieval and late interaction (L8): keep BM25’s lexical robustness and add dense semantic recall.', ru: 'На out-of-domain BEIR BM25 — устойчивый бейзлайн, обходящий обычный dense (напр. BM25 ≈ 0.43 vs DPR ≈ 0.38 nDCG@10 в среднем по задачам). Dense выигрывает in-domain, где обучающее распределение совпадает с запросами, но деградирует вне домена, потому что выученное семантическое пространство не переносится; у точного совпадения термов BM25 такой зависимости от домена нет. Это и мотивирует hybrid-поиск и late interaction (L8): сохранить лексическую устойчивость BM25 и добавить семантический recall.' } },

  // ───────────────────────── L8 · The Alliance ─────────────────────────
  { id: 'l8-late', lectures: ['08'], type: 'concept',
    q: { en: 'Late interaction: how does ColBERT differ from a bi-encoder (one vector) and a cross-encoder (full attention)? Where does it sit on the cost/detail axis?', ru: 'Late interaction: чем ColBERT отличается от bi (один вектор) и cross (полное внимание) и где он на оси цена/детальность?' },
    a: { en: 'A bi-encoder pools each side into a single vector and interacts once (one dot product) — cheap but lossy, because pooling forgets which token matched what. A cross-encoder reads q and d jointly with full cross-attention — maximally detailed but uncacheable and O(N). ColBERT keeps one vector per token, precomputes the doc-token vectors offline (like a bi-encoder), and interacts only at query time via MaxSim: each query token finds its best-matching doc token, and those maxes are summed. That preserves token-level matching while still caching the doc side — the middle ground of cost vs detail.', ru: 'Bi-encoder пулит каждую сторону в один вектор и взаимодействует однажды (один dot-product) — дёшево, но с потерями: пулинг забывает, какой токен с чем совпал. Cross-encoder читает q и d совместно полным cross-attention — максимально детально, но не кэшируется и O(N). ColBERT хранит вектор на токен, предпосчитывает токен-вектора документа офлайн (как bi-encoder) и взаимодействует только на запросе через MaxSim: каждый токен запроса находит лучший токен документа, и эти максимумы суммируются. Так сохраняется потокенное сопоставление при кэшировании стороны документа — это середина между ценой и детальностью.' } },

  { id: 'l8-maxsim', lectures: ['08'], type: 'compute',
    q: { en: 'Compute MaxSim from a token×token similarity matrix: take each query token’s row-max, then sum. Show on the relevant and the “lexical trap” doc why one perfect match (“bank” 0.98) still loses.', ru: 'Посчитай MaxSim по матрице токен×токен сходств: бери максимум строки на каждый токен запроса, затем сумма. Покажи на релевантном документе и на «лексической ловушке», почему одно идеальное совпадение («bank» 0.98) всё равно проигрывает.' },
    a: { en: 'MaxSim(q,d) = Σ_i max_j (E_qᵢ · E_dⱼ): for each query-token row, take its single best doc-token match, then sum those row-maxes. For q = (river, bank, flood) the relevant doc “the riverside plain flooded” scores 0.90 + 0.50 + 0.95 = 2.35 — every token found a partner. The trap doc “the bank approved a loan” nails “bank” at 0.98 but leaves “river” (0.20) and “flood” (0.12) with no partner, summing to only 1.30. Because MaxSim adds up many good matches rather than rewarding one loud one, 2.35 > 1.30 and the genuinely relevant passage wins.', ru: 'MaxSim(q,d) = Σ_i max_j (E_qᵢ · E_dⱼ): для каждой строки токена запроса берём одно лучшее совпадение токена документа, затем суммируем эти максимумы строк. Для q = (river, bank, flood) релевантный документ «the riverside plain flooded» даёт 0.90 + 0.50 + 0.95 = 2.35 — каждый токен нашёл партнёра. Документ-ловушка «the bank approved a loan» идеально ловит «bank» (0.98), но оставляет «river» (0.20) и «flood» (0.12) без пары, в сумме всего 1.30. Поскольку MaxSim складывает много хороших совпадений, а не награждает одно громкое, 2.35 > 1.30 — и побеждает по-настоящему релевантный отрывок.' },
    work: [
      'MaxSim(q,d) = SUM_i  max_j ( E_q_i . E_d_j )',
      'q = (river, bank, flood)',
      '',
      'relevant  d = "the riverside plain flooded"',
      '  row(river): best partner "riverside" = 0.90',
      '  row(bank) : best partner "riverside" = 0.50  (no exact "bank" token)',
      '  row(flood): best partner "flooded"   = 0.95',
      '  MaxSim = 0.90 + 0.50 + 0.95 = 2.35',
      '',
      'lexical trap  d = "the bank approved a loan"',
      '  row(river): no partner = 0.20',
      '  row(bank) : "bank"     = 0.98   <- one perfect match',
      '  row(flood): no partner = 0.12',
      '  MaxSim = 0.20 + 0.98 + 0.12 = 1.30',
      '',
      '2.35 > 1.30  ->  many matches beat one loud match' ] },

  { id: 'l8-splade', lectures: ['08'], type: 'concept',
    q: { en: 'SPLADE: how are the sparse weights produced (MLM logits → log(1+ReLU) → FLOPS regularizer), and why does the result stay inverted-index compatible?', ru: 'SPLADE: как получаются разрежённые веса (MLM-логиты → log(1+ReLU) → FLOPS-регуляризатор) и почему результат остаётся совместим с инвертированным индексом?' },
    a: { en: 'For each input token the masked-language-modeling head emits a logit over the whole BERT vocabulary (|V| = 30,522). The weight of vocabulary word j is w_j = Σ_(i∈input) log(1 + ReLU(z_ij)): ReLU drops the (mostly negative) logits and log saturates the large ones. A FLOPS regularizer penalizes dense vectors during training, so the model spends its mass on a few high-value terms and almost everything else is exactly zero. The surviving nonzero terms are vocabulary words with weights — i.e. a sparse vector that drops straight into the same posting lists and inverted index as BM25, while also lighting up expansion terms never typed in the text.', ru: 'Для каждого входного токена голова маскированного языкового моделирования выдаёт логит по всему словарю BERT (|V| = 30,522). Вес слова словаря j равен w_j = Σ_(i∈вход) log(1 + ReLU(z_ij)): ReLU отбрасывает (в основном отрицательные) логиты, а log насыщает большие. FLOPS-регуляризатор штрафует плотные вектора при обучении, поэтому модель тратит массу на немногие ценные термины, а почти всё остальное ровно ноль. Уцелевшие ненулевые термы — это слова словаря с весами, то есть разрежённый вектор, ложащийся прямо в те же постинг-листы и инвертированный индекс, что и BM25, при этом зажигая ещё и термины расширения, не введённые в тексте.' } },

  { id: 'l8-splade-compute', lectures: ['08'], type: 'compute',
    q: { en: 'Compute SPLADE term weights w = log(1+ReLU(logit)) from raw logits, identify the expansion terms, then compute the sparse dot against a document.', ru: 'Посчитай веса SPLADE w = log(1+ReLU(logit)) из сырых логитов, укажи термы-расширение, затем посчитай sparse-dot с документом.' },
    a: { en: 'With logits (2.0, 0.5, 2.5, 1.2) for (river, bank, flood, water), ReLU keeps them all positive and w = log(1+logit): river log(3.0)=1.0986, bank log(1.5)=0.4055, flood log(3.5)=1.2528, water log(2.2)=0.7885. The query was only “river flood”, so bank (0.4055) and water (0.7885) carry positive weight without being typed — they are expansion terms the model lit up, with “water” the brightest newcomer. The score is the sparse dot over shared terms: round each product to 4 places and sum the rounded products, 0.9887 + 0.2839 + 0.7517 + 1.0251 = 3.0494 — the same inverted-index arithmetic as BM25, just a richer signal.', ru: 'При логитах (2.0, 0.5, 2.5, 1.2) для (river, bank, flood, water) ReLU оставляет их все положительными и w = log(1+logit): river log(3.0)=1.0986, bank log(1.5)=0.4055, flood log(3.5)=1.2528, water log(2.2)=0.7885. Запрос был лишь «river flood», поэтому bank (0.4055) и water (0.7885) несут положительный вес, хотя их не вводили, — это термы-расширение, зажжённые моделью, причём «water» — самый яркий новичок. Оценка — sparse-dot по общим термам: округляем каждое произведение до 4 знаков и суммируем округлённые: 0.9887 + 0.2839 + 0.7517 + 1.0251 = 3.0494 — та же арифметика инвертированного индекса, что у BM25, лишь с богаче сигналом.' },
    work: [
      'w_j = log(1 + ReLU(logit_j))',
      'query logits (river, bank, flood, water) = (2.0, 0.5, 2.5, 1.2)',
      '  w_river = log(1+2.0) = log(3.0) = 1.0986',
      '  w_bank  = log(1+0.5) = log(1.5) = 0.4055   <- expansion',
      '  w_flood = log(1+2.5) = log(3.5) = 1.2528',
      '  w_water = log(1+1.2) = log(2.2) = 0.7885   <- expansion (query was "river flood")',
      '',
      'doc weights  w_d = (0.90, 0.70, 0.60, 1.30)  for (river, bank, flood, water)',
      'sparse dot = SUM over shared terms  w_q * w_d :',
      '  1.0986*0.90 = 0.9887',
      '  0.4055*0.70 = 0.2839',
      '  1.2528*0.60 = 0.7517',
      '  0.7885*1.30 = 1.0251',
      '  dot = 0.9887 + 0.2839 + 0.7517 + 1.0251 = 3.0494',
      '  (weights rounded to 4 dp; products use the rounded weights → 3.0494, the deck/data value)' ] },

  { id: 'l8-splade-flops', lectures: ['08'], type: 'compute',
    q: { en: 'Write the SPLADE training objective and the FLOPS regularizer mathematically, then show on a tiny batch why FLOPS pushes each vocabulary term to fire in only a few documents (short posting lists) instead of everywhere.', ru: 'Запиши цель обучения SPLADE и FLOPS-регуляризатор математически, затем покажи на мини-батче, почему FLOPS заставляет каждый терм словаря «загораться» лишь в немногих документах (короткие постинг-листы), а не везде.' },
    a: { en: 'SPLADE trains a ranking loss (InfoNCE / cross-entropy over a positive and negatives) plus sparsity regularizers: L = L_rank + λ_q·FLOPS(q) + λ_d·FLOPS(d). FLOPS is a differentiable proxy for query cost: for each vocabulary term j take its mean activation over the batch ā_j = (1/B) Σ_i w_ij, then FLOPS = Σ_j (ā_j)². Squaring the per-term batch-mean punishes any term that is active across many documents — exactly the terms that build long posting lists and many float-multiplies at query time — so the model is driven to keep each term firing in only a few docs and to push most of the |V| = 30,522 terms to exactly zero (they then add 0² = 0 and never enter the index). λ is the dial: larger λ ⇒ sparser, faster, slightly less expressive vectors.', ru: 'SPLADE обучает ранжирующий лосс (InfoNCE / кросс-энтропия по позитиву и негативам) плюс регуляризаторы разрежённости: L = L_rank + λ_q·FLOPS(q) + λ_d·FLOPS(d). FLOPS — дифференцируемая мера стоимости запроса: для каждого слова словаря j берём его среднюю активацию по батчу ā_j = (1/B) Σ_i w_ij, затем FLOPS = Σ_j (ā_j)². Квадрат средней по терму штрафует любой терм, активный во многих документах — именно они строят длинные постинг-листы и множество умножений на запросе, — поэтому модель вынуждена держать каждый терм активным лишь в немногих документах и гнать почти все |V| = 30 522 терма ровно в ноль (тогда они добавляют 0² = 0 и не попадают в индекс). λ — ручка: больше λ ⇒ разрежённее, быстрее, чуть менее выразительные вектора.' },
    work: [
      'L = L_rank + λ_q·FLOPS(q) + λ_d·FLOPS(d)',
      'FLOPS = Σ_j (ā_j)² ,   ā_j = (1/B) Σ_i w_ij   (mean of term j over a B-doc batch)',
      '',
      'why squaring punishes "active everywhere" — one term, batch B = 4:',
      '  term in ALL 4 docs (w=1):  ā = 4·1/4 = 1.00  → cost ā² = 1.0000',
      '  term in 1 of 4 docs (w=1): ā = 1·1/4 = 0.25  → cost ā² = 0.0625',
      '  same per-doc weight, but "everywhere" costs 16× more',
      '',
      'whole vocab (4 terms, batch B = 4):',
      '  DENSE  every doc fires all 4 terms → ā = (1, 1, 1, 1)         FLOPS = 4·1²   = 4.00',
      '  SPARSE doc i fires only term i     → ā = (.25, .25, .25, .25)  FLOPS = 4·.25² = 0.25',
      '  ⇒ FLOPS prefers SPARSE by 16× ; terms driven to 0 add 0² = 0 (leave the index)',
    ] },

  { id: 'l8-hybrid', lectures: ['08'], type: 'concept',
    q: { en: 'Why are lexical and dense retrieval complementary (BEIR evidence), and when does hybrid NOT help?', ru: 'Почему лексика и dense комплементарны (BEIR) и когда гибрид НЕ помогает?' },
    a: { en: 'Lexical (BM25/SPLADE) nails exact terms, rare tokens and out-of-domain queries; dense catches paraphrase and semantic matches with no shared words. They fail on different queries, so fusing the two lists covers cases neither covers alone — which is why hybrid is strong on BEIR. Hybrid stops helping (or hurts) when one ranker is far weaker than the other (it only adds noise), when the two are highly correlated (no new coverage to add), or when score-based fusion is used without calibrating the incomparable score scales first.', ru: 'Лексика (BM25/SPLADE) ловит точные термы, редкие токены и out-of-domain запросы; dense ловит перефраз и семантические совпадения без общих слов. Они ошибаются на разных запросах, поэтому слияние двух списков покрывает случаи, что не покрывает ни один по отдельности, — отсюда сила гибрида на BEIR. Гибрид перестаёт помогать (или вредит), когда один ранкер сильно слабее другого (он лишь добавляет шум), когда оба сильно коррелированы (нечего добавить к покрытию) или когда score-based слияние применяют, не откалибровав сперва несравнимые шкалы оценок.' } },

  { id: 'l8-rrf-hybrid', lectures: ['08', '03'], type: 'compute',
    q: { en: 'Hybrid RRF by hand (k=60): fuse a sparse and a dense ranking with score(d)=Σ 1/(60+rank) and show the consensus doc beating the sparse ranker’s #1 that the dense ranker buries.', ru: 'Гибрид RRF руками (k=60): слей разрежённый и плотный список через score(d)=Σ 1/(60+rank) и покажи, как консенсус обходит «#1» разрежённого, которого плотный хоронит.' },
    a: { en: 'RRF ignores score magnitudes and fuses by rank: score(d) = Σ_lists 1/(60 + rank). D₁ is the sparse ranker’s #1 (a loud lexical match) but the dense ranker ranks it 5th, giving 1/61 + 1/65 = 0.0318. The consensus doc D₂ is ranked 2nd by sparse and 1st by dense, giving 1/62 + 1/61 = 0.0325 — the highest, so D₂ wins and D₁ falls to 3rd. Two solid agreeing ranks sum higher than one great rank plus one bad one: RRF rewards agreement, not a lopsided loud vote, and needs no score calibration.', ru: 'RRF игнорирует величину оценок и сливает по рангам: score(d) = Σ_списки 1/(60 + ранг). D₁ — «#1» разрежённого ранкера (громкое лексическое совпадение), но плотный ставит его 5-м, давая 1/61 + 1/65 = 0.0318. Консенсусный D₂ стоит 2-м у разрежённого и 1-м у плотного, давая 1/62 + 1/61 = 0.0325 — это максимум, поэтому D₂ выигрывает, а D₁ падает на 3-е место. Два средних согласных ранга в сумме больше, чем один отличный плюс один плохой: RRF награждает согласие, а не однобокий громкий голос, и не требует калибровки шкал.' },
    work: [
      'score(d) = 1/(60 + rank_sparse) + 1/(60 + rank_dense)',
      '',
      '          rank_sparse  rank_dense   score',
      '  D2          2            1         1/62 + 1/61 = 0.01613 + 0.01639 = 0.0325',
      '  D3          3            2         1/63 + 1/62 = 0.0320',
      '  D1          1            5         1/61 + 1/65 = 0.01639 + 0.01538 = 0.0318',
      '  D4         ...          ...                                       = 0.0315',
      '  D5         ...          ...                                       = 0.0310',
      '',
      'fused order:  D2 > D3 > D1 > D4 > D5',
      'D1 was sparse #1 but dense buried it -> consensus D2 wins' ] },

  { id: 'l8-fusion-convex', lectures: ['08'], type: 'concept',
    q: { en: 'Convex / normalized score-combination fusion (α·dense + (1−α)·sparse, with min-max or z-score normalization) vs RRF: what does calibration buy and cost?', ru: 'Выпуклое / нормализованное слияние по оценкам (α·dense + (1−α)·sparse с min-max или z-score нормировкой) против RRF: что даёт и чего стоит калибровка?' },
    a: { en: 'Score combination fuses on the raw relevance scores: convex weighting computes α·dense + (1−α)·sparse, but only after the two incomparable score scales are normalized — min-max maps each list’s scores to [0,1] (simple but outlier-sensitive), z-score standardizes by mean and std. Done right this can be sharper than RRF because it uses score magnitudes (how confident each ranker is), not just ranks, and lets you tune α per workload. The cost is calibration: you must estimate and maintain the normalization and the weight, and it is brittle to scale drift and outliers. RRF skips all of that — it uses only ranks, so it needs no calibration and is the robust default; you reach for convex fusion when you can afford to tune and want the extra signal.', ru: 'Слияние по оценкам работает на сырых баллах релевантности: выпуклое взвешивание считает α·dense + (1−α)·sparse, но только после нормировки двух несравнимых шкал — min-max отображает баллы каждого списка в [0,1] (просто, но чувствительно к выбросам), z-score стандартизует по среднему и std. При правильной настройке это может быть точнее RRF, потому что использует величину оценок (насколько уверен каждый ранкер), а не только ранги, и позволяет тюнить α под нагрузку. Цена — калибровка: надо оценивать и поддерживать нормировку и вес, и метод хрупок к сдвигу шкал и выбросам. RRF всё это пропускает — он использует лишь ранги, поэтому не требует калибровки и служит устойчивым выбором по умолчанию; к выпуклому слиянию обращаются, когда можно позволить тюнинг и нужен дополнительный сигнал.' } },

  { id: 'l8-colbert-storage', lectures: ['08'], type: 'compute',
    q: { en: 'ColBERT storage, back-of-envelope: estimate the per-token index size for a corpus, compare it to a single-vector bi-encoder index, and show how ColBERTv2 residual compression (≈20–36 B/vec) shrinks it.', ru: 'Хранение ColBERT, прикидка на салфетке: оцени размер потокенного индекса для корпуса, сравни с одноквекторным bi-encoder индексом и покажи, как остаточное сжатие ColBERTv2 (≈20–36 Б/вектор) его ужимает.' },
    a: { en: 'A per-token index stores one vector for every token in the corpus, so its size is (#tokens) × dim × bytes/float. For 1M docs × ~100 tokens = 100M token-vectors at dim 128 and fp16 (2 bytes) that is 100M × 256 B = 25.6 GB — naïvely 256 bytes per vector. A bi-encoder stores one vector per document, so 1M × 256 B = 0.256 GB: the per-token index is ~100× larger (the token-per-doc factor). ColBERTv2 fixes this with residual compression — store a cluster centroid id plus a tiny quantized residual, ≈ 20–36 bytes/vector instead of 256 — a 6–10× shrink (here 32 B/vec → 3.2 GB). On MS MARCO this is the documented ≈ 286 GiB → 27 GiB drop. That is why late interaction is powerful but storage-hungry until compressed.', ru: 'Потокенный индекс хранит по вектору на каждый токен корпуса, поэтому его размер — (число токенов) × dim × байт/float. Для 1M документов × ~100 токенов = 100M токен-векторов при dim 128 и fp16 (2 байта) это 100M × 256 Б = 25.6 ГБ — наивно 256 байт на вектор. Bi-encoder хранит один вектор на документ, то есть 1M × 256 Б = 0.256 ГБ: потокенный индекс ~в 100 раз больше (множитель «токенов на документ»). ColBERTv2 чинит это остаточным сжатием — хранит id центроида кластера плюс крошечный квантованный остаток, ≈ 20–36 байт/вектор вместо 256 — сжатие в 6–10× (здесь 32 Б/вектор → 3.2 ГБ). На MS MARCO это документированное падение ≈ 286 ГиБ → 27 ГиБ. Поэтому late interaction мощный, но прожорлив по памяти, пока его не сжали.' },
    work: [
      'per-token index size = (#tokens) * dim * bytes/float',
      '',
      'corpus: 1,000,000 docs * ~100 tokens/doc = 100,000,000 token-vectors',
      'dim = 128, fp16 = 2 bytes  ->  naive 128*2 = 256 bytes/vector',
      '  naive total = 100e6 * 256 B = 25.6 GB',
      '',
      'bi-encoder (one vector PER DOC):',
      '  1e6 * 256 B = 0.256 GB     -> per-token index ~100x bigger',
      '',
      'ColBERTv2 residual compression: centroid id + tiny residual',
      '  ~32 B/vec instead of 256  ->  100e6 * 32 B = 3.2 GB   (8x shrink)',
      '  range 20-36 B/vec  ->  6-10x',
      'MS MARCO (documented): 286 GiB naive -> 27 GiB compressed' ] },

  { id: 'l8-ltr-compute', lectures: ['08'], type: 'compute',
    q: { en: 'Learning to Rank by hand: with sᵢ=1.5, sⱼ=0.3 compute the RankNet probability P=σ(sᵢ−sⱼ), its cross-entropy cost, the gradient, the ΔnDCG of the swap, and the LambdaRank force λ.', ru: 'Learning to Rank руками: при sᵢ=1.5, sⱼ=0.3 посчитай вероятность RankNet P=σ(sᵢ−sⱼ), её кросс-энтропийную стоимость, градиент, ΔnDCG обмена и силу LambdaRank λ.' },
    a: { en: 'The score difference is sᵢ−sⱼ = 1.2, so RankNet’s P(i≻j) = σ(1.2) = 0.7685 — already leaning the right way but not confident, with cost = log(1+e^−1.2) = 0.2633 (not yet zero). LambdaRank skips differentiating the metric and defines the force directly: gradient = 1 − σ(1.2) = 0.2315, and the swap [j,i]→[i,j] lifts nDCG from 0.6309 to 1.0, so ΔnDCG = 0.3691. The lambda is λ = gradient · ΔnDCG = 0.2315 · 0.3691 = 0.0854 — a force pulling i up and j down, scaled so that swaps which move the metric more pull harder. Pointwise scores each doc alone, pairwise (RankNet) learns the order of pairs, listwise optimizes the whole list.', ru: 'Разность оценок sᵢ−sⱼ = 1.2, поэтому RankNet P(i≻j) = σ(1.2) = 0.7685 — уже склоняется в верную сторону, но неуверенно, со стоимостью cost = log(1+e^−1.2) = 0.2633 (ещё не ноль). LambdaRank не дифференцирует метрику, а сразу задаёт силу: gradient = 1 − σ(1.2) = 0.2315, а обмен [j,i]→[i,j] поднимает nDCG с 0.6309 до 1.0, значит ΔnDCG = 0.3691. Лямбда λ = gradient · ΔnDCG = 0.2315 · 0.3691 = 0.0854 — сила, тянущая i вверх и j вниз, масштабированная так, что обмены, сильнее двигающие метрику, тянут сильнее. Pointwise скорит документ отдельно, pairwise (RankNet) учит порядок пар, listwise оптимизирует весь список.' },
    work: [
      's_i = 1.5,  s_j = 0.3   ->   s_i - s_j = 1.2',
      '',
      'RankNet:  P(i > j) = sigma(1.2) = 1/(1+e^-1.2) = 0.7685',
      'cost (label=1) = -log P = log(1 + e^-1.2) = 0.2633',
      '',
      'LambdaRank:',
      '  gradient = 1 - sigma(1.2) = 1 - 0.7685 = 0.2315',
      '  swap [j,i] -> [i,j]:  nDCG  0.6309 -> 1.0',
      '  dNDCG = 1.0 - 0.6309 = 0.3691',
      '  lambda = gradient * dNDCG = 0.2315 * 0.3691 = 0.0854',
      '',
      'pointwise: score each doc | pairwise: order pairs | listwise: whole list' ] },

  { id: 'l8-ranknet-cost', lectures: ['08'], type: 'compute',
    q: { en: 'Derive the RankNet pairwise cost: starting from P_ij = σ(sᵢ−sⱼ) and a target label, write the cross-entropy, simplify it for the “i should rank above j” case, and evaluate it at sᵢ−sⱼ=1.2.', ru: 'Выведи парную стоимость RankNet: из P_ij = σ(sᵢ−sⱼ) и целевой метки запиши кросс-энтропию, упрости для случая «i должен стоять выше j» и вычисли при sᵢ−sⱼ=1.2.' },
    a: { en: 'Let the score difference be Δ = sᵢ−sⱼ and P_ij = σ(Δ). With a target label P̄ (1 if i≻j, 0 if j≻i, ½ if tied) the cost is the binary cross-entropy C = −P̄ log P_ij − (1−P̄) log(1−P_ij). When i should rank above j (P̄=1) only the first term survives: C = −log σ(Δ). Using the identity −log σ(Δ) = log(1+e^−Δ), the cost is C = log(1+e^−Δ). At Δ=1.2 that is log(1+e^−1.2) = 0.2633 — matching −log σ(1.2) since σ(1.2)=0.7685. The gradient with respect to Δ is ∂C/∂Δ = −(1−σ(Δ)) = −(1−0.7685) = −0.2315, i.e. push sᵢ up and sⱼ down; this magnitude 0.2315 is exactly the factor LambdaRank then scales by |ΔnDCG|.', ru: 'Пусть разность оценок Δ = sᵢ−sⱼ и P_ij = σ(Δ). При целевой метке P̄ (1 если i≻j, 0 если j≻i, ½ при равенстве) стоимость — бинарная кросс-энтропия C = −P̄ log P_ij − (1−P̄) log(1−P_ij). Когда i должен стоять выше j (P̄=1), остаётся лишь первый член: C = −log σ(Δ). По тождеству −log σ(Δ) = log(1+e^−Δ) стоимость равна C = log(1+e^−Δ). При Δ=1.2 это log(1+e^−1.2) = 0.2633 — совпадает с −log σ(1.2), ведь σ(1.2)=0.7685. Градиент по Δ равен ∂C/∂Δ = −(1−σ(Δ)) = −(1−0.7685) = −0.2315, то есть толкаем sᵢ вверх, sⱼ вниз; именно эту величину 0.2315 LambdaRank затем масштабирует на |ΔnDCG|.' },
    work: [
      'Delta = s_i - s_j ,   P_ij = sigma(Delta)',
      'target  Pbar = 1 (i > j) | 0 (j > i) | 0.5 (tie)',
      '',
      'cross-entropy:  C = -Pbar*log P_ij - (1-Pbar)*log(1-P_ij)',
      'case i > j  (Pbar = 1):',
      '  C = -log sigma(Delta) = log(1 + e^-Delta)',
      '',
      'evaluate at Delta = 1.2:',
      '  sigma(1.2) = 0.7685',
      '  C = -log(0.7685) = log(1 + e^-1.2) = 0.2633',
      '',
      'gradient:  dC/dDelta = -(1 - sigma(Delta)) = -(1 - 0.7685) = -0.2315',
      '  -> push s_i up, s_j down; |0.2315| is the factor LambdaRank * |dNDCG|' ] },

  { id: 'l8-listwise', lectures: ['08'], type: 'concept',
    q: { en: 'Listwise objectives: contrast ListNet (top-one permutation probability) and ListMLE (Plackett–Luce permutation likelihood). Why optimize the whole list rather than pairs?', ru: 'Listwise-цели: сравни ListNet (вероятность «топ-один» перестановки) и ListMLE (правдоподобие перестановки Плакетта–Льюса). Зачем оптимизировать весь список, а не пары?' },
    a: { en: 'Listwise methods define a loss over the whole ordering, not isolated pairs. ListNet uses the top-one probability: from scores s it forms a distribution P(d first) = softmax(s) = e^(s_d)/Σ e^(s_k), and minimizes the cross-entropy between the score-induced and the label-induced top-one distributions. ListMLE goes further and maximizes the likelihood of the entire ground-truth permutation under the Plackett–Luce model — repeatedly “pick the next item” by softmax over the remaining scores: P(π) = Π_i e^(s_π(i)) / Σ_(k≥i) e^(s_π(k)). Optimizing the list is closer to ranking metrics (which depend on the full order, especially the top) and avoids the pairwise assumption that all swaps are independent — at the price of costlier training.', ru: 'Listwise-методы задают лосс по всему порядку, а не по отдельным парам. ListNet использует вероятность «топ-один»: из оценок s строит распределение P(d первый) = softmax(s) = e^(s_d)/Σ e^(s_k) и минимизирует кросс-энтропию между распределениями «топ-один», порождёнными оценками и метками. ListMLE идёт дальше и максимизирует правдоподобие всей истинной перестановки в модели Плакетта–Льюса — многократно «выбирай следующий элемент» через softmax по оставшимся оценкам: P(π) = Π_i e^(s_π(i)) / Σ_(k≥i) e^(s_π(k)). Оптимизация списка ближе к ранжирующим метрикам (которые зависят от всего порядка, особенно верха) и избегает парного допущения о независимости всех обменов — ценой более дорогого обучения.' } },

  { id: 'l8-ltr-line', lectures: ['08'], type: 'concept',
    q: { en: 'Trace RankNet → LambdaRank → LambdaMART: what does each step add?', ru: 'Проследи RankNet → LambdaRank → LambdaMART: что добавляет каждый шаг?' },
    a: { en: 'RankNet turns a pairwise preference into a probability of the score difference, P(i≻j)=σ(sᵢ−sⱼ), trained with cross-entropy — but it optimizes pairwise accuracy, which is not the ranking metric. LambdaRank notices you never need the cost itself, only its gradient, and scales each pair’s gradient by |ΔnDCG| (the metric change from swapping i and j) so that swaps near the top, where the metric moves most, pull hardest — directly steering toward nDCG. LambdaMART puts those λ-gradients inside gradient-boosted regression trees instead of a neural net, giving the robust, feature-friendly LTR workhorse that long dominated LETOR/MSLR leaderboards.', ru: 'RankNet превращает парное предпочтение в вероятность разности оценок, P(i≻j)=σ(sᵢ−sⱼ), и учится кросс-энтропией — но оптимизирует парную точность, а не ранжирующую метрику. LambdaRank замечает, что сама стоимость не нужна, нужен лишь её градиент, и масштабирует градиент каждой пары на |ΔnDCG| (изменение метрики от обмена i и j), чтобы обмены наверху, где метрика двигается сильнее всего, тянули сильнее — целясь прямо в nDCG. LambdaMART кладёт эти λ-градиенты в градиентный бустинг регрессионных деревьев вместо нейросети, давая устойчивую, дружелюбную к признакам рабочую лошадку LTR, долго доминировавшую в LETOR/MSLR.' } },

{ id: 'syn-sparse-dense', lectures: ['03', '07', '08'], type: 'concept',
    q: { en: 'Put BM25, a dense bi-encoder, ColBERT (late interaction) and SPLADE side by side: what does each store per document, how does matching happen, and what is each strong and weak at?', ru: 'Поставь рядом BM25, плотный bi-encoder, ColBERT (late interaction) и SPLADE: что каждый хранит на документ, как происходит сопоставление и в чём сила и слабость каждого?' },
    a: { en: 'BM25 stores a sparse bag of term frequencies in an inverted index and matches by exact overlapping terms — strong on rare/exact tokens and out-of-domain, blind to synonyms. A dense bi-encoder stores one pooled vector per doc and matches by a single dot product in an ANN index — strong on paraphrase and semantics, but one vector forgets which token matched and degrades out-of-domain. ColBERT stores one vector per token and matches by MaxSim (each query token takes its best doc token, summed) — token-level precision with a cacheable doc side, but a roughly 100x larger index until compressed. SPLADE stores a learned sparse vector over the BERT vocabulary (with expansion terms) in the SAME inverted index as BM25 — lexical compatibility plus learned semantics. Hybrid then fuses a lexical and a dense list (e.g. RRF) to cover what each one misses.', ru: 'BM25 хранит разрежённый мешок частот термов в инвертированном индексе и сопоставляет по точному пересечению термов — силён на редких/точных токенах и вне домена, слеп к синонимам. Плотный bi-encoder хранит один пулинг-вектор на документ и сопоставляет одним скалярным произведением в ANN-индексе — силён на перефразе и семантике, но один вектор забывает, какой токен совпал, и деградирует вне домена. ColBERT хранит вектор на токен и сопоставляет через MaxSim (каждый токен запроса берёт лучший токен документа, затем сумма) — потокенная точность при кэшируемой стороне документа, но индекс примерно в 100× больше, пока не сжат. SPLADE хранит выученный разрежённый вектор по словарю BERT (с термами-расширения) в ТОМ ЖЕ инвертированном индексе, что и BM25 — лексическая совместимость плюс выученная семантика. Hybrid затем сливает лексический и плотный списки (напр. RRF), покрывая то, что каждый по отдельности пропускает.' },
    work: [
      'model     stored per doc        match op            strong              index',
      'BM25      sparse term freqs     exact term overlap  rare/exact, OOD     inverted',
      'bi-enc    1 pooled vector       1 dot product       paraphrase          ANN (small)',
      'ColBERT   1 vector PER TOKEN    MaxSim (Σ row-max)  token precision     per-token (~100× big)',
      'SPLADE    sparse vocab vector   sparse dot          lexical + expansion inverted',
      'hybrid    both lists            RRF / convex fuse   coverage union      both',
    ] },

  { id: 'syn-cosine', lectures: ['02', '05', '06', '07'], type: 'concept',
    q: { en: 'Cosine similarity recurs from L2 to L7. Trace what the vectors being compared are at each stage — TF-IDF/BoW (L2), static word2vec/GloVe (L5), contextual token/sentence (L6), bi-encoder query/doc (L7) — and what changes about what "similar" means.', ru: 'Косинусное сходство проходит сквозь L2–L7. Проследи, что за векторы сравниваются на каждом этапе — TF-IDF/BoW (L2), статический word2vec/GloVe (L5), контекстный токен/предложение (L6), запрос/документ bi-encoder (L7) — и как меняется смысл слова «похоже».' },
    a: { en: 'The operation cos = (a·b)/(‖a‖‖b‖) never changes; the vectors do. In L2 they are sparse TF-IDF/BoW counts, so cosine measures lexical overlap (shared words) and the lexical gap bites — "couch" is orthogonal to "sofa". In L5 they are dense static word2vec/GloVe vectors, so cosine measures distributional similarity and synonyms finally land close, but every word still has ONE vector (polysemy collapses). In L6 they are contextual token/sentence vectors from a transformer, so cosine compares meaning-in-context — yet raw transformer vectors are anisotropic, so cosines are all high until contrastive training or whitening spreads them out. In L7 they are a trained bi-encoder\'s query and doc vectors in one shared space, so cosine IS the relevance score the ANN index ranks by. Same angle, progressively richer vectors.', ru: 'Операция cos = (a·b)/(‖a‖‖b‖) не меняется; меняются векторы. В L2 это разрежённые счётчики TF-IDF/BoW, поэтому косинус меряет лексическое пересечение (общие слова) и кусает lexical gap — «couch» ортогонален «sofa». В L5 это плотные статические word2vec/GloVe, поэтому косинус меряет дистрибутивное сходство и синонимы наконец оказываются рядом, но у каждого слова всё ещё ОДИН вектор (полисемия схлопывается). В L6 это контекстные векторы токена/предложения из трансформера, поэтому косинус сравнивает смысл-в-контексте — но сырые векторы анизотропны, и косинусы все высокие, пока контрастное обучение или whitening их не раздвинут. В L7 это запрос и документ обученного bi-encoder в одном общем пространстве, поэтому косинус И ЕСТЬ оценка релевантности, по которой ранжирует ANN-индекс. Тот же угол — всё более богатые векторы.' } },

  { id: 'syn-goodhart', lectures: ['01', '04'], type: 'concept',
    q: { en: 'Connect Goodhart\'s law (L1) to evaluation practice (L4): how do offline metrics, click logs, significance testing and A/B tests each fail or defend against gaming a proxy?', ru: 'Свяжи закон Гудхарта (L1) с практикой оценивания (L4): как оффлайн-метрики, клик-логи, тесты значимости и A/B по отдельности проваливаются или защищают от гейминга прокси?' },
    a: { en: 'Goodhart: once a measure is the target it stops measuring well. Click-through is a proxy for satisfaction, so optimizing it rewards clickbait and inherits position bias (a top result is clicked for being on top, not for being best). Offline graded metrics (nDCG/MAP) on fixed qrels resist click bias but can be over-fit and depend on annotator agreement — a low Cohen\'s κ caps the resolution. A paired significance test (t-test / Wilcoxon on per-query deltas) guards against celebrating noise — a +2% mean with huge per-query variance is not real — but testing many variants inflates false positives, needing a Bonferroni-style correction. The ultimate defence is an online A/B test (or interleaving / IPS to debias logs): triangulate several signals so no single number can be gamed.', ru: 'Гудхарт: как только метрика становится целью, она перестаёт мерить хорошо. CTR — прокси удовлетворённости, поэтому его оптимизация награждает кликбейт и наследует position bias (верхний результат кликают за то, что он сверху, а не лучший). Оффлайн-градуированные метрики (nDCG/MAP) на фиксированных qrels устойчивее к клик-смещению, но переобучаемы и зависят от согласия аннотаторов — низкая κ Коэна ограничивает разрешение. Парный тест значимости (t-тест / Wilcoxon по per-query разностям) защищает от радости по шуму — +2% при огромной per-query дисперсии нереальны, — но проверка многих вариантов раздувает ложные срабатывания и требует поправки Bonferroni. Высшая защита — онлайн A/B (или interleaving / IPS для дебиаса логов): триангулируй несколько сигналов, чтобы ни одно число нельзя было загеймить.' } },

  { id: 'syn-recall-ceiling', lectures: ['04', '07', '08'], type: 'concept',
    q: { en: 'The "recall ceiling" ties L4, L7 and L8 together. Explain why a cascade\'s final quality is bounded by first-stage recall, how you measure it (L4), and how late interaction / hybrid (L8) raise the ceiling.', ru: '«Recall-потолок» связывает L4, L7 и L8. Объясни, почему итоговое качество каскада ограничено recall первого этапа, как это измерить (L4) и как late interaction / hybrid (L8) поднимают потолок.' },
    a: { en: 'A reranker only reorders the candidates it is handed, so any relevant doc the retriever misses is lost forever — the best achievable nDCG@k of the whole pipeline is bounded by the retriever\'s recall@k (L7). You measure this with recall@k / a recall-aware evaluation (L4): tune the retriever for recall and the reranker for precision-at-the-top, and watch stage-1 recall@k as the true ceiling. To lift the ceiling you make stage-1 recall higher: hybrid retrieval fuses lexical + dense so each covers the other\'s misses, ColBERT late interaction recovers token-level matches a single pooled vector drops, and SPLADE adds learned expansion terms — all L8 moves that put more relevant docs into the candidate set before reranking even begins.', ru: 'Реранкер лишь переставляет выданных кандидатов, поэтому любой релевантный документ, пропущенный ретривером, потерян навсегда — лучший достижимый nDCG@k всего конвейера ограничен recall@k ретривера (L7). Это измеряют через recall@k / recall-чувствительную оценку (L4): ретривер настраивают на recall, реранкер — на точность наверху, а recall@k первого этапа — это и есть истинный потолок. Чтобы поднять потолок, повышают recall первого этапа: hybrid сливает лексику + dense, чтобы каждый покрывал промахи другого, ColBERT late interaction возвращает потокенные совпадения, теряемые одним пулинг-вектором, а SPLADE добавляет выученные термы-расширения — всё это ходы L8, кладущие больше релевантных документов в набор кандидатов ещё до реранка.' } },

  { id: 'syn-pipeline', lectures: ['01', '03', '07', '08'], type: 'concept',
    q: { en: 'Design the modern retrieval stack end-to-end: name each stage from query to final ranking, what runs there, what it optimizes, and the order-of-magnitude candidate count at each step.', ru: 'Спроектируй современный поисковый стек целиком: назови каждый этап от запроса до финального ранжирования, что там работает, что оптимизируется и порядок числа кандидатов на каждом шаге.' },
    a: { en: 'Stage 0 — query understanding / expansion. Stage 1 retrieve (~10^6 → 10^3): cheap and wide over the whole index, optimizing recall — BM25/SPLADE in an inverted index and/or a dense bi-encoder in an ANN index, often fused with RRF (hybrid). Stage 2 rank (~10^3 → 10^2): a learning-to-rank model (LambdaMART or a light neural ranker) over features, optimizing the ranking metric. Stage 3 rerank (~10^2 → 10): an expensive cross-encoder (or ColBERT MaxSim) reading each pair jointly, optimizing precision@k. Each stage spends about 10x more compute on about 10x fewer candidates so total latency stays under SLA, and the whole pipeline is capped by stage-1 recall — you cannot rerank what you never retrieved.', ru: 'Этап 0 — понимание/расширение запроса. Этап 1 retrieve (~10^6 → 10^3): дёшево и вширь по всему индексу, оптимизируем recall — BM25/SPLADE в инвертированном индексе и/или плотный bi-encoder в ANN-индексе, часто слитые через RRF (hybrid). Этап 2 rank (~10^3 → 10^2): модель learning-to-rank (LambdaMART или лёгкий нейроранкер) по признакам, оптимизируем ранжирующую метрику. Этап 3 rerank (~10^2 → 10): дорогой cross-encoder (или ColBERT MaxSim) читает пару совместно, оптимизируем precision@k. Каждый этап тратит примерно в 10× больше вычислений на примерно в 10× меньше кандидатов, удерживая суммарную задержку под SLA, а весь конвейер ограничен recall первого этапа — нельзя переранжировать то, что не извлёк.' },
    work: [
      'stage     candidates       runs                          optimizes',
      'retrieve  10^6 → 10^3      BM25/SPLADE + dense, RRF       recall',
      'rank      10^3 → 10^2      LambdaMART / light ranker      ranking metric',
      'rerank    10^2 → 10        cross-encoder / ColBERT        precision@k',
      'rule: ~10× more compute on ~10× fewer docs · capped by stage-1 recall',
    ] },

  { id: 'syn-train-objectives', lectures: ['05', '06', '07', '08'], type: 'compute',
    q: { en: 'Write the training objective at each step of the representation-learning arc — word2vec skip-gram (L5), InfoNCE/NT-Xent (L6), DPR in-batch contrastive (L7), SPLADE ranking+FLOPS and RankNet (L8) — and say what they share.', ru: 'Выпиши цель обучения на каждом шаге дуги обучения представлений — word2vec skip-gram (L5), InfoNCE/NT-Xent (L6), in-batch контрастное обучение DPR (L7), SPLADE ranking+FLOPS и RankNet (L8) — и скажи, что у них общего.' },
    a: { en: 'They are all "pull the positive in, push negatives out," differing in how negatives are sourced and scored. word2vec skip-gram with negative sampling pushes one true context up and k sampled words down. InfoNCE / NT-Xent generalizes from k fixed negatives to a softmax over a whole batch at temperature τ. DPR is exactly InfoNCE with in-batch negatives — an N×N similarity matrix S = Q·Dᵀ, row-wise softmax cross-entropy with the diagonal as the positive. SPLADE adds a ranking loss plus a sparsity penalty (λ·FLOPS) to keep the learned-sparse vector index-friendly. RankNet switches from contrastive to a pairwise preference, P(i≻j)=σ(s_i−s_j) trained with cross-entropy, and LambdaRank then scales each pair\'s gradient by |ΔnDCG|. The shared spine: a softmax/sigmoid over similarity differences, optimized by gradient descent.', ru: 'Все они — «притяни позитив, оттолкни негативы», различаясь тем, откуда берутся и как скорятся негативы. word2vec skip-gram с negative sampling тянет один истинный контекст вверх и k сэмплированных слов вниз. InfoNCE / NT-Xent обобщает с k фиксированных негативов на softmax по всему батчу при температуре τ. DPR — это в точности InfoNCE с in-batch негативами: матрица сходств N×N S = Q·Dᵀ, построчная softmax-кросс-энтропия с диагональю как позитивом. SPLADE добавляет ранжирующий лосс плюс штраф разрежённости (λ·FLOPS), чтобы выученно-разрежённый вектор дружил с индексом. RankNet переходит от контрастного обучения к парному предпочтению, P(i≻j)=σ(s_i−s_j) с кросс-энтропией, а LambdaRank масштабирует градиент каждой пары на |ΔnDCG|. Общий стержень: softmax/сигмоида по разностям сходств, оптимизируемая градиентным спуском.' },
    work: [
      'skip-gram (NS) : L = −log σ(u_c·v_w) − Σ_(i=1..k) log σ(−u_(n_i)·v_w)',
      'InfoNCE/NT-Xent: L = −log[ exp(sim⁺/τ) / Σ_x exp(sim_x/τ) ]',
      'DPR in-batch   : S = Q·Dᵀ (N×N) ; L = −(1/N) Σ_i log[ exp(S_ii/τ) / Σ_j exp(S_ij/τ) ]',
      'SPLADE         : L = L_rank + λ_q·FLOPS(q) + λ_d·FLOPS(d)',
      'RankNet        : P(i≻j) = σ(s_i−s_j) ; C = −log σ(s_i−s_j) ; λ_Lambda = ∂C · |ΔnDCG|',
      'shared spine   : softmax/σ over similarity differences · pull + / push − · by SGD',
    ] }
];
